import type { Attempt, AttendanceDay, ClassRoom, DB, Lang, Mark, Quiz, Role, User } from './types'
import { percent } from './utils'

export const userById = (db: DB, id?: string | null): User | undefined => (id ? db.users.find((u) => u.id === id) : undefined)

export const classById = (db: DB, id?: string | null): ClassRoom | undefined =>
  id ? db.classes.find((c) => c.id === id) : undefined

export const schoolById = (db: DB, id?: string | null) => (id ? db.schools.find((s) => s.id === id) : undefined)

export const studentClassIds = (db: DB, studentId: string): string[] =>
  db.enrollments.filter((e) => e.studentId === studentId && e.status === 'active').map((e) => e.classId)

export const classStudents = (db: DB, classId: string): User[] => {
  const ids = db.enrollments.filter((e) => e.classId === classId && e.status === 'active').map((e) => e.studentId)
  return ids.map((id) => userById(db, id)).filter((u): u is User => !!u)
}

export const teacherClassIds = (db: DB, teacherId: string): string[] => {
  const owned = db.classes.filter((c) => c.teacherId === teacherId).map((c) => c.id)
  const taught = db.sessions.filter((s) => s.teacherId === teacherId).map((s) => s.classId)
  return Array.from(new Set([...owned, ...taught]))
}

export const isClassTeacher = (db: DB, teacherId: string, classId: string): boolean =>
  db.classes.some((c) => c.id === classId && c.teacherId === teacherId)

export const guardianChildIds = (db: DB, parentId: string): string[] =>
  db.parentLinks.filter((l) => l.parentId === parentId && l.status === 'approved').map((l) => l.studentId)

export const guardianChildren = (db: DB, parentId: string): User[] =>
  guardianChildIds(db, parentId)
    .map((id) => userById(db, id))
    .filter((u): u is User => !!u)

export const canViewClass = (db: DB, actor: User | null | undefined, classId: string): boolean => {
  if (!actor) return false
  if (actor.role === 'admin') return classById(db, classId)?.schoolId === actor.schoolId
  if (actor.role === 'teacher') return teacherClassIds(db, actor.id).includes(classId)
  if (actor.role === 'student') return studentClassIds(db, actor.id).includes(classId)
  if (actor.role === 'parent') {
    const children = guardianChildIds(db, actor.id)
    return children.some((childId) => studentClassIds(db, childId).includes(classId))
  }
  return false
}

/** Central privacy gate for individual student records. */
export const canViewStudent = (db: DB, actor: User | null | undefined, studentId: string): boolean => {
  if (!actor) return false
  const student = userById(db, studentId)
  if (!student || student.role !== 'student') return false
  if (actor.role === 'student') return actor.id === studentId
  if (actor.role === 'parent') return guardianChildIds(db, actor.id).includes(studentId)
  if (actor.role === 'teacher') {
    const mine = new Set(teacherClassIds(db, actor.id))
    return studentClassIds(db, studentId).some((cid) => mine.has(cid))
  }
  if (actor.role === 'admin') return student.schoolId === actor.schoolId
  return false
}

/** Teachers can edit records only for classes they own (or administer). */
export const canManageClass = (db: DB, actor: User | null | undefined, classId: string): boolean => {
  if (!actor) return false
  if (actor.role === 'admin') return classById(db, classId)?.schoolId === actor.schoolId
  if (actor.role === 'teacher') return isClassTeacher(db, actor.id, classId)
  return false
}

export const visibleClasses = (db: DB, actor: User | null | undefined): ClassRoom[] => {
  if (!actor) return []
  if (actor.role === 'admin') return db.classes.filter((c) => c.schoolId === actor.schoolId)
  if (actor.role === 'teacher') {
    const ids = new Set(teacherClassIds(db, actor.id))
    return db.classes.filter((c) => ids.has(c.id))
  }
  if (actor.role === 'student') {
    const ids = new Set(studentClassIds(db, actor.id))
    return db.classes.filter((c) => ids.has(c.id))
  }
  const ids = new Set(guardianChildIds(db, actor.id).flatMap((sid) => studentClassIds(db, sid)))
  return db.classes.filter((c) => ids.has(c.id))
}

export const visibleStudents = (db: DB, actor: User | null | undefined): User[] => {
  if (!actor) return []
  if (actor.role === 'admin') return db.users.filter((u) => u.role === 'student' && u.schoolId === actor.schoolId)
  if (actor.role === 'teacher') {
    const ids = new Set(teacherClassIds(db, actor.id).flatMap((cid) => classStudents(db, cid).map((s) => s.id)))
    return db.users.filter((u) => ids.has(u.id))
  }
  if (actor.role === 'parent') return guardianChildren(db, actor.id)
  return [actor]
}

export interface AttendanceSummary {
  present: number
  absent: number
  late: number
  excused: number
  total: number
  pct: number
  days: AttendanceDay[]
}

export const attendanceSummary = (db: DB, studentId: string, classId?: string): AttendanceSummary => {
  const relevant = db.attendance
    .filter((d) => !classId || d.classId === classId)
    .filter((d) => studentClassIds(db, studentId).includes(d.classId))
    .map((d) => ({ ...d, entries: d.entries.filter((e) => e.studentId === studentId) }))
    .filter((d) => d.entries.length > 0)
    .sort((a, b) => b.date.localeCompare(a.date))

  let present = 0
  let absent = 0
  let late = 0
  let excused = 0
  for (const day of relevant) {
    const status = day.entries[0].status
    if (status === 'present') present++
    else if (status === 'absent') absent++
    else if (status === 'late') late++
    else excused++
  }
  const total = relevant.length
  const attended = present + late
  return { present, absent, late, excused, total, pct: percent(attended, total), days: relevant }
}

export const studentAttendanceStatus = (day: AttendanceDay, studentId: string): string =>
  day.entries.find((e) => e.studentId === studentId)?.status ?? 'not-marked'

export const attemptsForStudent = (db: DB, studentId: string): Attempt[] =>
  db.attempts.filter((a) => a.studentId === studentId).sort((a, b) => b.submittedAt.localeCompare(a.submittedAt))

export const attemptsForQuiz = (db: DB, quizId: string, studentId?: string): Attempt[] =>
  db.attempts.filter((a) => a.quizId === quizId && (!studentId || a.studentId === studentId))

export const quizMaxScore = (quiz: Quiz): number => quiz.questions.reduce((sum, q) => sum + q.points, 0)

/** Results are visible only when the teacher's visibility rule allows it. */
export const quizResultsVisible = (quiz: Quiz, now: Date = new Date()): boolean => {
  if (quiz.showResults === 'immediately') return true
  if (quiz.showResults === 'after_due') {
    if (!quiz.dueAt) return true
    const due = new Date(`${quiz.dueAt}T23:59:59`)
    return now.getTime() > due.getTime()
  }
  return false
}

export const openQuizzesFor = (db: DB, studentId: string): Quiz[] => {
  const classIds = new Set(studentClassIds(db, studentId))
  const now = new Date()
  return db.quizzes.filter((q) => {
    if (!q.published || !classIds.has(q.classId)) return false
    if (q.openAt && new Date(`${q.openAt}T00:00:00`) > now) return false
    if (q.dueAt && new Date(`${q.dueAt}T23:59:59`) < now) return false
    const used = attemptsForQuiz(db, q.id, studentId).length
    return used < q.attemptsAllowed
  })
}

export const marksForStudent = (db: DB, studentId: string): Array<{ mark: Mark; assessment: (typeof db.assessments)[number] }> =>
  db.marks
    .filter((m) => m.studentId === studentId)
    .map((mark) => ({ mark, assessment: db.assessments.find((a) => a.id === mark.assessmentId)! }))
    .filter((row) => row.assessment && row.assessment.published)
    .sort((a, b) => b.assessment.date.localeCompare(a.assessment.date))

export const subjectProgress = (
  db: DB,
  studentId: string,
): Array<{ subjectId: string; pct: number; count: number }> => {
  const bySubject = new Map<string, { earned: number; max: number; count: number }>()
  for (const { mark, assessment } of marksForStudent(db, studentId)) {
    const entry = bySubject.get(assessment.subjectId) || { earned: 0, max: 0, count: 0 }
    entry.earned += mark.marks
    entry.max += assessment.maxMarks
    entry.count += 1
    bySubject.set(assessment.subjectId, entry)
  }
  return Array.from(bySubject.entries()).map(([subjectId, v]) => ({
    subjectId,
    pct: percent(v.earned, v.max),
    count: v.count,
  }))
}

export interface LeaderboardRow {
  studentId: string
  name: string
  avatarColor: string
  points: number
  isCurrentUser?: boolean
}

export const leaderboardFor = (db: DB, classId: string, currentUserId?: string): LeaderboardRow[] => {
  const students = classStudents(db, classId)
  const points = new Map<string, number>()
  for (const e of db.activity.filter((a) => a.classId === classId)) {
    points.set(e.studentId, (points.get(e.studentId) || 0) + e.points)
  }
  return students
    .filter((s) => !db.leaderboardOptOut.includes(s.id))
    .map((s) => ({
      studentId: s.id,
      name: s.name.split(' ')[0],
      avatarColor: s.avatarColor,
      points: points.get(s.id) || 0,
      isCurrentUser: s.id === currentUserId,
    }))
    .sort((a, b) => b.points - a.points || a.name.localeCompare(b.name))
}

export const classAverage = (db: DB, classId: string, assessmentId?: string): number => {
  const assessmentIds = db.assessments
    .filter((a) => a.classId === classId && a.published && (!assessmentId || a.id === assessmentId))
    .map((a) => a.id)
  const relevant = db.marks.filter((m) => assessmentIds.includes(m.assessmentId))
  if (!relevant.length) return 0
  let earned = 0
  let max = 0
  for (const m of relevant) {
    const a = db.assessments.find((x) => x.id === m.assessmentId)
    if (a) {
      earned += m.marks
      max += a.maxMarks
    }
  }
  return percent(earned, max)
}

export const unreadNotificationCount = (db: DB, userId: string): number =>
  db.notifications.filter((n) => n.userId === userId && !n.read).length

export const pendingParentLinksForAdmin = (db: DB, schoolId: string) =>
  db.parentLinks.filter((l) => {
    if (l.status !== 'pending') return false
    const student = userById(db, l.studentId)
    return student?.schoolId === schoolId
  })

export const lowAttendanceStudents = (db: DB, classId: string, threshold: number) =>
  classStudents(db, classId)
    .map((s) => ({ student: s, summary: attendanceSummary(db, s.id, classId) }))
    .filter((row) => row.summary.total > 0 && row.summary.pct < threshold)
    .sort((a, b) => a.summary.pct - b.summary.pct)

export const roleLabelKey = (role: Role) => `role.${role}`

export const contentLanguageLabel = (lang: Lang): string =>
  ({ en: 'English', hi: 'हिन्दी', mr: 'मराठी', bn: 'বাংলা', ta: 'தமிழ்', te: 'తెలుగు' } as Record<Lang, string>)[lang] ?? lang

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import type { Attempt, DB, NotificationKind, OutboxItem, Role, Toast, User } from './types'
import { buildSeed, DB_VERSION, SEED_STORAGE_KEY } from './seed'
import { hashPassword, makeSalt, uid, normaliseCode, isOnline as readOnline } from './utils'
import { userById } from './access'
import { gradeQuiz } from './quiz'

const SESSION_KEY = 'vidyagram.session'

export interface SignupInput {
  role: Role
  name: string
  email: string
  phone?: string
  password: string
  language: User['language']
  schoolId: string
  gradeLevel?: number
  section?: string
  subjectIds?: string[]
  classCode?: string
  consentGiven: boolean
  relationship?: string
}

interface AppContextValue {
  db: DB
  ready: boolean
  currentUser: User | null
  online: boolean
  toasts: Toast[]
  pendingSync: number
  login: (identifier: string, password: string) => Promise<{ ok: boolean; error?: string }>
  signup: (input: SignupInput) => Promise<{ ok: boolean; error?: string; user?: User }>
  logout: () => void
  updateUser: (userId: string, patch: Partial<User>) => void
  mutate: (fn: (db: DB) => void) => void
  notify: (userId: string, kind: NotificationKind, title: string, body: string, link?: string) => void
  awardPoints: (studentId: string, classId: string, points: number, reason: string) => void
  awardBadge: (userId: string, badgeKey: string) => void
  queueOffline: (kind: OutboxItem['kind'], payload: Record<string, unknown>) => void
  syncOutbox: () => Promise<void>
  resetDemo: () => Promise<void>
  toast: (tone: Toast['tone'], title: string, description?: string) => void
  dismissToast: (id: string) => void
}

const AppContext = createContext<AppContextValue | null>(null)

export function AppProvider({ children }: { children: ReactNode }) {
  const [db, setDb] = useState<DB | null>(null)
  const [sessionId, setSessionId] = useState<string | null>(() => {
    try {
      return localStorage.getItem(SESSION_KEY)
    } catch {
      return null
    }
  })
  const [online, setOnline] = useState<boolean>(readOnline)
  const [toasts, setToasts] = useState<Toast[]>([])
  const booting = useRef(false)

  const toast = useCallback((tone: Toast['tone'], title: string, description?: string) => {
    const id = uid('toast')
    setToasts((prev) => [...prev.slice(-3), { id, tone, title, description }])
    window.setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 5200)
  }, [])

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id))
  }, [])

  // Boot: restore persisted data or build the sample dataset.
  useEffect(() => {
    if (booting.current) return
    booting.current = true
    let cancelled = false
    const boot = async () => {
      let loaded: DB | null = null
      try {
        const raw = localStorage.getItem(SEED_STORAGE_KEY)
        if (raw) {
          const parsed = JSON.parse(raw) as DB
          if (parsed.version === DB_VERSION) loaded = parsed
        }
      } catch {
        loaded = null
      }
      if (!loaded) loaded = await buildSeed()
      if (cancelled) return
      setDb(loaded)
      try {
        localStorage.setItem(SEED_STORAGE_KEY, JSON.stringify(loaded))
      } catch {
        /* storage full or blocked */
      }
    }
    void boot()
    return () => {
      cancelled = true
    }
  }, [])

  // Persist on every change.
  useEffect(() => {
    if (!db) return
    try {
      localStorage.setItem(SEED_STORAGE_KEY, JSON.stringify(db))
    } catch {
      toast('error', 'Storage is full', 'Remove a download to free space on this device.')
    }
  }, [db, toast])

  useEffect(() => {
    try {
      if (sessionId) localStorage.setItem(SESSION_KEY, sessionId)
      else localStorage.removeItem(SESSION_KEY)
    } catch {
      /* ignore */
    }
  }, [sessionId])

  useEffect(() => {
    const on = () => setOnline(true)
    const off = () => setOnline(false)
    window.addEventListener('online', on)
    window.addEventListener('offline', off)
    return () => {
      window.removeEventListener('online', on)
      window.removeEventListener('offline', off)
    }
  }, [])

  const currentUser = useMemo(() => (db && sessionId ? userById(db, sessionId) ?? null : null), [db, sessionId])

  const mutate = useCallback((fn: (draft: DB) => void) => {
    setDb((prev) => {
      if (!prev) return prev
      const draft: DB = typeof structuredClone === 'function' ? structuredClone(prev) : JSON.parse(JSON.stringify(prev))
      fn(draft)
      return draft
    })
  }, [])

  const notify = useCallback(
    (userId: string, kind: NotificationKind, title: string, body: string, link?: string) => {
      mutate((draft) => {
        draft.notifications.unshift({
          id: uid('notif'),
          userId,
          kind,
          title,
          body,
          link,
          read: false,
          createdAt: new Date().toISOString(),
        })
      })
    },
    [mutate],
  )

  const awardPoints = useCallback(
    (studentId: string, classId: string, points: number, reason: string) => {
      mutate((draft) => {
        draft.activity.push({
          id: uid('act'),
          studentId,
          classId,
          points,
          reason,
          at: new Date().toISOString(),
        })
      })
    },
    [mutate],
  )

  const awardBadge = useCallback(
    (userId: string, badgeKey: string) => {
      mutate((draft) => {
        if (draft.userBadges.some((b) => b.userId === userId && b.badgeKey === badgeKey)) return
        draft.userBadges.push({ id: uid('ub'), userId, badgeKey, awardedAt: new Date().toISOString() })
        draft.notifications.unshift({
          id: uid('notif'),
          userId,
          kind: 'system',
          title: 'New badge earned',
          body: 'Open your profile to see your latest achievement.',
          link: '/profile',
          read: false,
          createdAt: new Date().toISOString(),
        })
      })
    },
    [mutate],
  )

  const login = useCallback(
    async (identifier: string, password: string): Promise<{ ok: boolean; error?: string }> => {
      if (!db) return { ok: false, error: 'auth.invalid' }
      const key = identifier.trim().toLowerCase()
      const phoneKey = identifier.replace(/\D/g, '')
      const user = db.users.find(
        (u) => u.email.toLowerCase() === key || (!!phoneKey && (u.phone || '').replace(/\D/g, '') === phoneKey),
      )
      if (!user) return { ok: false, error: 'auth.invalid' }
      if (user.disabled) return { ok: false, error: 'auth.disabled' }
      const hash = await hashPassword(password, user.salt)
      if (hash !== user.passwordHash) return { ok: false, error: 'auth.invalid' }
      setSessionId(user.id)
      return { ok: true }
    },
    [db],
  )

  const signup = useCallback(
    async (input: SignupInput): Promise<{ ok: boolean; error?: string; user?: User }> => {
      if (!db) return { ok: false, error: 'auth.invalid' }
      const emailKey = input.email.trim().toLowerCase()
      if (db.users.some((u) => u.email.toLowerCase() === emailKey)) return { ok: false, error: 'auth.exists' }
      const salt = makeSalt()
      const passwordHash = await hashPassword(input.password, salt)
      const newUser: User = {
        id: uid('usr'),
        role: input.role,
        name: input.name.trim(),
        email: emailKey,
        phone: input.phone?.trim() || undefined,
        passwordHash,
        salt,
        language: input.language,
        avatarColor: 'bg-brand-100 text-brand-800',
        schoolId: input.schoolId,
        createdAt: new Date().toISOString(),
        lowDataMode: false,
        consentGiven: input.consentGiven,
        consentAt: input.consentGiven ? new Date().toISOString() : undefined,
      }
      let error: string | undefined
      mutate((draft) => {
        if (input.role === 'student') {
          newUser.gradeLevel = input.gradeLevel
          newUser.section = input.section
          newUser.rollNo = String(draft.users.filter((u) => u.role === 'student' && u.gradeLevel === input.gradeLevel).length + 1).padStart(2, '0')
          newUser.inviteCode = `${input.name.split(' ')[0].toUpperCase()}-${Math.floor(1000 + Math.random() * 8999)}`
        }
        if (input.role === 'teacher') newUser.subjectIds = input.subjectIds || []
        if (input.role === 'parent') newUser.relationship = input.relationship || 'Guardian'
        draft.users.push(newUser)

        if (input.role === 'student' && input.classCode) {
          const cls = draft.classes.find((c) => normaliseCode(c.code) === normaliseCode(input.classCode || ''))
          if (!cls) {
            error = 'auth.classCodeInvalid'
            return
          }
          draft.enrollments.push({
            id: uid('enr'),
            classId: cls.id,
            studentId: newUser.id,
            joinedAt: new Date().toISOString(),
            status: 'active',
          })
          draft.notifications.unshift({
            id: uid('notif'),
            userId: newUser.id,
            kind: 'class',
            title: `Welcome to ${cls.name}`,
            body: 'Your class materials and live sessions will appear on your dashboard.',
            link: '/classes',
            read: false,
            createdAt: new Date().toISOString(),
          })
        }
      })
      if (error) return { ok: false, error }
      setSessionId(newUser.id)
      return { ok: true, user: newUser }
    },
    [db, mutate],
  )

  const logout = useCallback(() => setSessionId(null), [])

  const updateUser = useCallback(
    (userId: string, patch: Partial<User>) => {
      mutate((draft) => {
        const u = draft.users.find((x) => x.id === userId)
        if (u) Object.assign(u, patch)
      })
    },
    [mutate],
  )

  const queueOffline = useCallback(
    (kind: OutboxItem['kind'], payload: Record<string, unknown>) => {
      mutate((draft) => {
        draft.outbox.push({ id: uid('out'), kind, payload, createdAt: new Date().toISOString() })
      })
    },
    [mutate],
  )

  const grantOfflineAchievements = useCallback(
    (draft: DB, studentId: string, classId?: string) => {
      const downloads = draft.downloads.filter((d) => d.userId === studentId)
      if (downloads.length >= 2 && !draft.userBadges.some((b) => b.userId === studentId && b.badgeKey === 'offlineLearner')) {
        draft.userBadges.push({ id: uid('ub'), userId: studentId, badgeKey: 'offlineLearner', awardedAt: new Date().toISOString() })
      }
      const bookmarks = draft.bookmarks.filter((b) => b.userId === studentId)
      if (bookmarks.length >= 3 && !draft.userBadges.some((b) => b.userId === studentId && b.badgeKey === 'bookworm')) {
        draft.userBadges.push({ id: uid('ub'), userId: studentId, badgeKey: 'bookworm', awardedAt: new Date().toISOString() })
      }
      if (classId) {
        const attempts = draft.attempts.filter((a) => a.studentId === studentId && a.quizId && draft.quizzes.find((q) => q.id === a.quizId)?.classId === classId)
        if (attempts.length >= 1 && !draft.userBadges.some((b) => b.userId === studentId && b.badgeKey === 'firstSteps')) {
          draft.userBadges.push({ id: uid('ub'), userId: studentId, badgeKey: 'firstSteps', awardedAt: new Date().toISOString() })
        }
        const strong = attempts.some((a) => a.maxScore > 0 && a.score / a.maxScore >= 0.8)
        if (strong && !draft.userBadges.some((b) => b.userId === studentId && b.badgeKey === 'quizStarter')) {
          draft.userBadges.push({ id: uid('ub'), userId: studentId, badgeKey: 'quizStarter', awardedAt: new Date().toISOString() })
        }
      }
    },
    [],
  )

  const syncOutbox = useCallback(async () => {
    if (!db || db.outbox.length === 0) return
    if (!readOnline()) {
      toast('info', 'Still offline', 'Your saved changes will sync when the connection returns.')
      return
    }
    const items = [...db.outbox]
    mutate((draft) => {
      for (const item of items) {
        if (item.kind === 'quiz-attempt') {
          const payload = item.payload as { quizId: string; studentId: string; answers: Record<string, string> }
          const quiz = draft.quizzes.find((q) => q.id === payload.quizId)
          if (!quiz) continue
          const graded = gradeQuiz(quiz, payload.answers)
          const attempt: Attempt = {
            id: uid('att'),
            quizId: quiz.id,
            studentId: payload.studentId,
            answers: payload.answers,
            score: graded.score,
            maxScore: graded.maxScore,
            autoGraded: true,
            submittedAt: new Date().toISOString(),
            syncedFromOffline: true,
          }
          draft.attempts.push(attempt)
          draft.activity.push({
            id: uid('act'),
            studentId: payload.studentId,
            classId: quiz.classId,
            points: 10 + Math.round((graded.score / Math.max(1, graded.maxScore)) * 20),
            reason: 'quiz-attempt-offline',
            at: attempt.submittedAt,
          })
          grantOfflineAchievements(draft, payload.studentId, quiz.classId)
        }
        if (item.kind === 'doubt') {
          const p = item.payload as { studentId: string; classId: string; subjectId: string; topic: string; question: string; attachmentName?: string }
          draft.doubts.unshift({
            id: uid('doubt'),
            studentId: p.studentId,
            classId: p.classId,
            subjectId: p.subjectId,
            topic: p.topic,
            question: p.question,
            attachmentName: p.attachmentName,
            status: 'open',
            createdAt: new Date().toISOString(),
            replies: [],
          })
          const cls = draft.classes.find((c) => c.id === p.classId)
          if (cls) {
            draft.notifications.unshift({
              id: uid('notif'),
              userId: cls.teacherId,
              kind: 'doubt',
              title: 'New doubt (synced from offline)',
              body: p.topic,
              link: '/doubts',
              read: false,
              createdAt: new Date().toISOString(),
            })
          }
        }
        if (item.kind === 'feedback') {
          const p = item.payload as { userId: string; role: Role; category: string; subject: string; message: string }
          draft.feedback.unshift({
            id: uid('fb'),
            userId: p.userId,
            role: p.role,
            category: p.category as never,
            subject: p.subject,
            message: p.message,
            status: 'new',
            createdAt: new Date().toISOString(),
          })
          const admins = draft.users.filter((u) => u.role === 'admin')
          for (const admin of admins) {
            draft.notifications.unshift({
              id: uid('notif'),
              userId: admin.id,
              kind: 'system',
              title: 'New feedback (synced from offline)',
              body: p.subject,
              link: '/admin/feedback',
              read: false,
              createdAt: new Date().toISOString(),
            })
          }
        }
      }
      draft.outbox = draft.outbox.filter((o) => !items.some((i) => i.id === o.id))
    })
    toast('success', 'Offline changes synced', `${items.length} saved item(s) are now on the school record.`)
  }, [db, mutate, toast, grantOfflineAchievements])

  // Auto-sync when connectivity returns.
  const previousOnline = useRef(online)
  useEffect(() => {
    if (!previousOnline.current && online && db && db.outbox.length > 0) {
      void syncOutbox()
    }
    previousOnline.current = online
  }, [online, db, syncOutbox])

  const resetDemo = useCallback(async () => {
    const fresh = await buildSeed()
    setSessionId(null)
    setDb(fresh)
    try {
      localStorage.setItem(SEED_STORAGE_KEY, JSON.stringify(fresh))
    } catch {
      /* ignore */
    }
    toast('success', 'Demo data restored', 'Sample classes, marks and resources are back to their original state.')
  }, [toast])

  const value = useMemo<AppContextValue | null>(() => {
    if (!db) return null
    return {
      db,
      ready: true,
      currentUser,
      online,
      toasts,
      pendingSync: db.outbox.length,
      login,
      signup,
      logout,
      updateUser,
      mutate,
      notify,
      awardPoints,
      awardBadge,
      queueOffline,
      syncOutbox,
      resetDemo,
      toast,
      dismissToast,
    }
  }, [
    db,
    currentUser,
    online,
    toasts,
    login,
    signup,
    logout,
    updateUser,
    mutate,
    notify,
    awardPoints,
    awardBadge,
    queueOffline,
    syncOutbox,
    resetDemo,
    toast,
    dismissToast,
  ])

  if (!value) {
    return (
      <div className="grid min-h-screen place-items-center bg-ink-50 p-6">
        <div className="flex flex-col items-center gap-4 text-center">
          <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-brand-600 text-2xl font-black text-white">V</div>
          <div>
            <p className="text-lg font-bold text-ink-900">VidyaGram</p>
            <p className="text-sm text-ink-500">Preparing your learning space…</p>
          </div>
          <div className="h-1.5 w-40 overflow-hidden rounded-full bg-ink-200" role="progressbar" aria-label="Loading">
            <div className="h-full w-1/2 animate-pulse rounded-full bg-brand-500" />
          </div>
        </div>
      </div>
    )
  }

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp(): AppContextValue {
  const ctx = useContext(AppContext)
  if (!ctx) throw new Error('useApp must be used inside AppProvider')
  return ctx
}

import type { Question, Quiz } from './types'

export interface GradeResult {
  score: number
  maxScore: number
  correct: Record<string, boolean>
}

const normalise = (value: string): string =>
  value
    .toLowerCase()
    .trim()
    .replace(/[.,!?;:'"“”‘’]/g, '')
    .replace(/\s+/g, ' ')

export const isAnswerCorrect = (question: Question, given: string): boolean => {
  if (question.type === 'mcq') return normalise(given) === normalise(question.answer)
  const accepted = [question.answer, ...(question.accept || [])].map(normalise)
  return accepted.includes(normalise(given))
}

/** Auto-grades objective questions only. */
export const gradeQuiz = (quiz: Quiz, answers: Record<string, string>): GradeResult => {
  let score = 0
  const correct: Record<string, boolean> = {}
  for (const question of quiz.questions) {
    const given = answers[question.id] || ''
    const ok = given.trim().length > 0 && isAnswerCorrect(question, given)
    correct[question.id] = ok
    if (ok) score += question.points
  }
  return { score, maxScore: quiz.questions.reduce((s, q) => s + q.points, 0), correct }
}

export const resultWhenLabel = (quiz: Quiz, dueLabel: string, manualLabel: string): string => {
  if (quiz.showResults === 'immediately') return ''
  if (quiz.showResults === 'after_due') return dueLabel
  return manualLabel
}

