import { Link } from 'react-router-dom'
import { useApp } from '../../lib/store'
import { useI18n } from '../../lib/i18n'
import {
  attendanceSummary,
  classStudents,
  lowAttendanceStudents,
  marksForStudent,
  visibleClasses,
} from '../../lib/access'
import { formatDate, formatTime, subjectLabel, todayISO } from '../../lib/utils'
import { Icon } from '../../components/Icon'
import { ClassSummaryCard, SessionCard, SubjectChip } from '../../components/shared'
import {
  Badge,
  Button,
  Callout,
  Card,
  EmptyState,
  PageHeader,
  SectionCard,
  StatCard,
  buttonClass,
} from '../../components/ui'

export function TeacherDashboard() {
  const { db, currentUser, online } = useApp()
  const { t, lang } = useI18n()
  if (!currentUser) return null

  const classes = visibleClasses(db, currentUser)
  const classIds = new Set(classes.map((c) => c.id))
  const students = db.users.filter(
    (u) => u.role === 'student' && db.enrollments.some((e) => e.classId && classIds.has(e.classId) && e.studentId === u.id && e.status === 'active'),
  )
  const today = todayISO()

  const todaySessions = db.sessions
    .filter((s) => classIds.has(s.classId) && s.date === today && s.status !== 'cancelled')
    .sort((a, b) => a.startTime.localeCompare(b.startTime))

  const upcoming = db.sessions
    .filter((s) => classIds.has(s.classId) && s.status === 'scheduled' && s.date > today)
    .sort((a, b) => `${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`))
    .slice(0, 3)

  const openDoubts = db.doubts
    .filter((d) => d.status === 'open' && classIds.has(d.classId))
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))

  const pendingGrading = db.assessments.filter((a) => classIds.has(a.classId) && (!a.graded || !a.published))

  const ungradedQuizzes = db.quizzes.filter((q) => classIds.has(q.classId) && !q.published)

  const threshold = db.schools.find((s) => s.id === currentUser.schoolId)?.lowAttendanceThreshold ?? 75
  const lowAttendance = classes.flatMap((c) =>
    lowAttendanceStudents(db, c.id, threshold).map((row) => ({ ...row, className: c.name })),
  )

  const markedToday = new Set(db.attendance.filter((a) => a.date === today && classIds.has(a.classId)).map((a) => a.classId))
  const attendancePct = students.length
    ? Math.round(
        students.reduce((sum, s) => sum + attendanceSummary(db, s.id).pct, 0) / Math.max(1, students.length),
      )
    : 0

  const recentAttempts = db.attempts
    .filter((a) => db.quizzes.some((q) => q.id === a.quizId && classIds.has(q.classId)))
    .sort((a, b) => b.submittedAt.localeCompare(a.submittedAt))
    .slice(0, 4)

  const pendingLinks = db.parentLinks.filter((l) => {
    if (l.status !== 'pending') return false
    const student = db.users.find((u) => u.id === l.studentId)
    return !!student && student.schoolId === currentUser.schoolId
  })

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('dash.hello', { name: currentUser.name.split(' ')[0] })}
        subtitle={t('dash.teacherSub')}
        eyebrow={classes.map((c) => c.name).join(' · ') || t('classes.noClasses')}
        icon="home"
        actions={
          <>
            <Link to="/live?schedule=1" className={buttonClass('secondary', 'md')}>
              <Icon name="video" size={17} /> {t('dash.scheduleClass')}
            </Link>
            <Link to="/attendance" className={buttonClass('primary', 'md')}>
              <Icon name="calendar" size={17} /> {t('dash.markAttendance')}
            </Link>
          </>
        }
      />

      {!online ? (
        <Callout tone="warn" title={t('state.offlineTitle')}>
          {t('state.offlineBody')} Attendance and marks you save now stay on this device until you reconnect.
        </Callout>
      ) : null}

      {classes.length === 0 ? (
        <EmptyState
          icon="users"
          title={t('classes.noClasses')}
          description={t('classes.teacherSub')}
          action={<Link to="/classes" className={buttonClass('primary')}>{t('classes.create')}</Link>}
        />
      ) : (
        <>
          <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
            <StatCard label={t('common.students')} value={students.length} hint={t('classes.members', { count: students.length })} icon="users" tone="brand" />
            <StatCard
              label={t('dash.markAttendance')}
              value={`${markedToday.size}/${classes.length}`}
              hint={t('dash.classesToday', { count: todaySessions.length })}
              icon="calendar"
              tone={markedToday.size === classes.length ? 'leaf' : 'saffron'}
            />
            <StatCard label={t('dash.openDoubts')} value={openDoubts.length} hint={t('doubt.teacherSub')} icon="message" tone={openDoubts.length ? 'clay' : 'leaf'} />
            <StatCard label={t('dash.pendingGrading')} value={pendingGrading.length + ungradedQuizzes.length} hint={t('marks.publishHint')} icon="clipboard" tone={pendingGrading.length + ungradedQuizzes.length ? 'saffron' : 'leaf'} />
          </div>

          <div className="grid gap-4 lg:grid-cols-3">
            <div className="space-y-4 lg:col-span-2">
              <SectionCard
                title={t('dash.todaySchedule')}
                subtitle={t('dash.classesToday', { count: todaySessions.length })}
                action={<Link to="/live" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>}
                icon="video"
                bodyClassName="space-y-2.5"
              >
                {todaySessions.length ? (
                  todaySessions.map((s) => (
                    <SessionCard
                      key={s.id}
                      session={s}
                      action={
                        <Link to="/live" className={buttonClass('secondary', 'sm')}>
                          {s.status === 'live' ? t('live.join') : t('common.open')}
                        </Link>
                      }
                    />
                  ))
                ) : (
                  <EmptyState icon="calendar" title={t('dash.noClassesToday')} description={t('dash.scheduleClass')} action={<Link to="/live?schedule=1" className={buttonClass('secondary', 'sm')}>{t('dash.scheduleClass')}</Link>} />
                )}
              </SectionCard>

              <SectionCard
                title={t('dash.openDoubts')}
                subtitle={t('doubt.teacherSub')}
                action={<Link to="/doubts" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>}
                icon="message"
                bodyClassName="space-y-2"
              >
                {openDoubts.length ? (
                  openDoubts.slice(0, 4).map((d) => {
                    const student = db.users.find((u) => u.id === d.studentId)
                    return (
                      <Link key={d.id} to="/doubts" className="flex items-start gap-2.5 rounded-xl border border-ink-200 p-2.5 hover:bg-ink-50">
                        <span className="mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-clay-50 text-clay-700"><Icon name="message" size={15} /></span>
                        <span className="min-w-0 flex-1">
                          <span className="flex flex-wrap items-center gap-1.5">
                            <span className="truncate text-xs font-bold text-ink-900">{d.topic}</span>
                            <SubjectChip subjectId={d.subjectId} />
                          </span>
                          <span className="mt-0.5 line-clamp-2 block text-[11px] text-ink-600">{d.question}</span>
                          <span className="mt-0.5 block text-[10px] text-ink-400">{doubtLabel(student?.name)} · {formatDate(d.createdAt.slice(0, 10), lang)}</span>
                        </span>
                        <Icon name="chevronRight" size={14} className="mt-1 shrink-0 text-ink-400" />
                      </Link>
                    )
                  })
                ) : (
                  <div className="rounded-xl border border-leaf-200 bg-leaf-50 p-3 text-sm text-leaf-900">
                    <p className="flex items-center gap-1.5 font-semibold"><Icon name="checkCircle" size={16} /> {t('doubt.noOpen')}</p>
                  </div>
                )}
              </SectionCard>

              <SectionCard title={t('dash.teacherClasses')} action={<Link to="/classes" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>} icon="users">
                <div className="grid gap-3 sm:grid-cols-2">
                  {classes.map((c) => (
                    <ClassSummaryCard key={c.id} cls={c}>
                      <div className="flex flex-wrap gap-1.5">
                        <Badge tone="ink" icon="clipboard">{classStudents(db, c.id).length} {t('common.students')}</Badge>
                        <Badge tone="brand" icon="calendar">{attendanceSummary(db, classStudents(db, c.id)[0]?.id || '').total ? `${Math.round(classStudents(db, c.id).reduce((s, st) => s + attendanceSummary(db, st.id, c.id).pct, 0) / Math.max(1, classStudents(db, c.id).length))}%` : '—'}</Badge>
                      </div>
                      <div className="mt-2 flex gap-2">
                        <Link to={`/classes`} className={buttonClass('secondary', 'sm', 'flex-1')}>{t('dash.manage')}</Link>
                        <Link to={`/live?class=${c.id}`} className={buttonClass('quiet', 'sm', 'flex-1')}>{t('nav.live')}</Link>
                      </div>
                    </ClassSummaryCard>
                  ))}
                </div>
              </SectionCard>
            </div>

            <div className="space-y-4">
              <SectionCard title={t('att.studentsBelow', { threshold })} subtitle={t('att.teacherSub')} action={<Link to="/attendance" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>} icon="alert" bodyClassName="space-y-1.5">
                {lowAttendance.length ? (
                  lowAttendance.slice(0, 5).map((row) => (
                    <div key={`${row.student.id}-${row.className}`} className="flex items-center justify-between gap-2 rounded-lg bg-clay-50 px-2.5 py-2">
                      <div className="min-w-0">
                        <p className="truncate text-xs font-semibold text-ink-800">{row.student.name}</p>
                        <p className="text-[10px] text-ink-500">{row.className} · {row.summary.present + row.summary.late}/{row.summary.total} {t('unit.days')}</p>
                      </div>
                      <Badge tone={row.summary.pct < 60 ? 'clay' : 'saffron'}>{row.summary.pct}%</Badge>
                    </div>
                  ))
                ) : (
                  <p className="rounded-lg bg-leaf-50 px-2.5 py-2 text-[11px] text-leaf-800">{t('att.good')} — {t('att.belowThreshold', { threshold })}.</p>
                )}
              </SectionCard>

              <SectionCard title={t('dash.pendingGrading')} icon="clipboard" bodyClassName="space-y-2">
                {pendingGrading.slice(0, 3).map((a) => (
                  <Link key={a.id} to="/marks" className="block rounded-lg border border-ink-200 p-2.5 hover:bg-ink-50">
                    <p className="text-xs font-semibold text-ink-800">{a.title}</p>
                    <p className="mt-0.5 text-[10px] text-ink-500">{subjectLabel(a.subjectId, t)} · {formatDate(a.date, lang)} · {a.published ? t('marks.noMarks') : t('common.draft')}</p>
                  </Link>
                ))}
                {ungradedQuizzes.map((q) => (
                  <Link key={q.id} to={`/quizzes/${q.id}`} className="block rounded-lg border border-ink-200 p-2.5 hover:bg-ink-50">
                    <p className="text-xs font-semibold text-ink-800">{q.title}</p>
                    <p className="mt-0.5 text-[10px] text-ink-500">{t('quiz.publishHint')}</p>
                  </Link>
                ))}
                {!pendingGrading.length && !ungradedQuizzes.length ? <p className="text-xs text-ink-500">{t('dash.allCaughtUp')}</p> : null}
              </SectionCard>

              <SectionCard title={t('quiz.submitted')} icon="checkCircle" bodyClassName="space-y-2">
                {recentAttempts.length ? recentAttempts.map((a) => {
                  const quiz = db.quizzes.find((q) => q.id === a.quizId)
                  const student = db.users.find((u) => u.id === a.studentId)
                  return (
                    <Link key={a.id} to={`/quizzes/${a.quizId}`} className="flex items-center justify-between gap-2 rounded-lg px-2 py-1.5 hover:bg-ink-50">
                      <span className="min-w-0">
                        <span className="block truncate text-xs font-semibold text-ink-800">{student?.name}</span>
                        <span className="block truncate text-[10px] text-ink-500">{quiz?.title}</span>
                      </span>
                      <Badge tone="brand">{a.score}/{a.maxScore}</Badge>
                    </Link>
                  )
                }) : <p className="text-xs text-ink-500">{t('quiz.noAttemptsYet')}</p>}
              </SectionCard>

              {pendingLinks.length ? (
                <SectionCard title={t('classes.guardianLinks')} icon="link" bodyClassName="space-y-2">
                  {pendingLinks.map((l) => {
                    const parent = db.users.find((u) => u.id === l.parentId)
                    const student = db.users.find((u) => u.id === l.studentId)
                    return (
                      <div key={l.id} className="rounded-lg bg-saffron-50 p-2.5">
                        <p className="text-xs font-semibold text-saffron-900">{parent?.name} → {student?.name}</p>
                        <p className="mt-0.5 text-[10px] text-saffron-800">{t('admin.approvals')} · {t('common.pending')}</p>
                      </div>
                    )
                  })}
                  <Link to="/admin/approvals" className={buttonClass('secondary', 'sm', 'w-full')}>{t('common.open')}</Link>
                </SectionCard>
              ) : null}

              <Card className="bg-brand-700 p-4 text-white">
                <p className="flex items-center gap-1.5 text-sm font-bold"><Icon name="sparkles" size={16} /> {t('nav.ai')}</p>
                <p className="mt-1 text-[11px] leading-relaxed text-brand-100">{t('ai.teacherSub')}</p>
                <Link to="/ai" className="mt-2 inline-flex min-h-9 items-center gap-1 rounded-lg bg-white px-3 text-xs font-bold text-brand-800">
                  {t('ai.lessonPlan')} <Icon name="arrowRight" size={14} />
                </Link>
              </Card>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            {[
              { to: '/quizzes?create=1', icon: 'clipboard' as const, label: t('dash.createQuiz') },
              { to: '/materials?upload=1', icon: 'upload' as const, label: t('dash.addMaterial') },
              { to: '/doubts', icon: 'message' as const, label: t('dash.viewDoubts') },
              { to: '/live?schedule=1', icon: 'video' as const, label: t('dash.scheduleClass') },
            ].map((item) => (
              <Link key={item.to} to={item.to} className="card flex items-center gap-2.5 p-3 hover:shadow-pop">
                <span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-brand-50 text-brand-700"><Icon name={item.icon} size={17} /></span>
                <span className="min-w-0 text-xs font-bold text-ink-900">{item.label}</span>
              </Link>
            ))}
          </div>

          {upcoming.length ? (
            <SectionCard title={t('dash.upcomingClasses')} icon="calendar" bodyClassName="space-y-2.5">
              {upcoming.map((s) => (
                <SessionCard key={s.id} session={s} compact action={<Link to="/live" className={buttonClass('secondary', 'sm')}>{t('common.open')}</Link>} />
              ))}
            </SectionCard>
          ) : null}
        </>
      )}
    </div>
  )
}

function doubtLabel(name?: string) {
  return name ? `Asked by ${name}` : 'Student question'
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { useApp } from '../../lib/store'
import { useI18n } from '../../lib/i18n'
import {
  attendanceSummary,
  classById,
  guardianChildren,
  marksForStudent,
  quizResultsVisible,
  studentClassIds,
} from '../../lib/access'
import { formatDate, formatTime, percent, subjectLabel } from '../../lib/utils'
import { Icon } from '../../components/Icon'
import { AnnouncementItem, AttendanceSnapshot, NotificationsPreview, SubjectChip } from '../../components/shared'
import {
  Avatar,
  Badge,
  Button,
  Callout,
  Card,
  EmptyState,
  PageHeader,
  ProgressBar,
  SectionCard,
  StatCard,
  buttonClass,
} from '../../components/ui'

export function ParentDashboard() {
  const { db, currentUser, online } = useApp()
  const { t, lang } = useI18n()
  const children = currentUser ? guardianChildren(db, currentUser.id) : []
  const [childId, setChildId] = useState(children[0]?.id || '')

  useEffect(() => {
    if (!children.some((c) => c.id === childId)) setChildId(children[0]?.id || '')
  }, [children, childId])

  if (!currentUser) return null

  if (!children.length) {
    return (
      <div>
        <PageHeader title={t('dash.hello', { name: currentUser.name.split(' ')[0] })} subtitle={t('dash.parentSub')} icon="home" />
        <EmptyState
          icon="link"
          title={t('parent.noChild')}
          description={t('parent.noChildHint')}
          action={<Link to="/parent/link" className={buttonClass('primary')}>{t('parent.linkTitle')}</Link>}
        />
      </div>
    )
  }

  const child = children.find((c) => c.id === childId) || children[0]
  const classIds = studentClassIds(db, child.id)
  const classes = classIds.map((id) => classById(db, id)).filter(Boolean)
  const summary = attendanceSummary(db, child.id)
  const results = marksForStudent(db, child.id)
  const overall = results.length
    ? percent(
        results.reduce((s, r) => s + r.mark.marks, 0),
        results.reduce((s, r) => s + r.assessment.maxMarks, 0),
      )
    : 0

  const now = new Date()
  const upcoming = db.sessions
    .filter((s) => classIds.includes(s.classId) && s.status === 'scheduled' && s.date >= now.toISOString().slice(0, 10))
    .sort((a, b) => `${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`))
    .slice(0, 3)

  const attempts = db.attempts
    .filter((a) => a.studentId === child.id)
    .sort((a, b) => b.submittedAt.localeCompare(a.submittedAt))
    .slice(0, 4)

  const announcements = db.announcements
    .filter(
      (a) =>
        a.schoolId === currentUser.schoolId &&
        (a.audience === 'parents' || a.audience === 'all') &&
        (!a.classId || classIds.includes(a.classId)),
    )
    .sort((a, b) => Number(!!b.pinned) - Number(!!a.pinned) || b.createdAt.localeCompare(a.createdAt))
    .slice(0, 2)

  const unread = db.notifications.filter((n) => n.userId === currentUser.id && !n.read)
  const threshold = db.schools.find((s) => s.id === child.schoolId)?.lowAttendanceThreshold ?? 75

  const subjectRows = Array.from(
    results.reduce<Map<string, { earned: number; max: number }>>((acc, r) => {
      const entry = acc.get(r.assessment.subjectId) || { earned: 0, max: 0 }
      entry.earned += r.mark.marks
      entry.max += r.assessment.maxMarks
      acc.set(r.assessment.subjectId, entry)
      return acc
    }, new Map()),
  ).map(([subjectId, v]) => ({ subjectId, pct: percent(v.earned, v.max) }))

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('dash.hello', { name: currentUser.name.split(' ')[0] })}
        subtitle={t('dash.parentSub')}
        eyebrow={child.name}
        icon="home"
        actions={<Link to="/parent/link" className={buttonClass('secondary', 'md')}><Icon name="link" size={17} /> {t('prof.linkedChildren')}</Link>}
      />

      {!online ? (
        <Callout tone="warn" title={t('state.offlineTitle')}>{t('state.offlineBody')}</Callout>
      ) : null}

      {children.length > 1 ? (
        <div className="flex flex-wrap items-center gap-2 rounded-xl border border-ink-200 bg-white p-2.5">
          <span className="px-1 text-xs font-semibold text-ink-500">{t('parent.chooseChild')}</span>
          {children.map((c) => (
            <button
              key={c.id}
              type="button"
              onClick={() => setChildId(c.id)}
              aria-pressed={c.id === child.id}
              className={`flex min-h-10 items-center gap-2 rounded-lg border px-2.5 text-xs font-semibold ${
                c.id === child.id ? 'border-brand-600 bg-brand-50 text-brand-800' : 'border-ink-200 text-ink-700 hover:bg-ink-50'
              }`}
            >
              <Avatar name={c.name} color={c.avatarColor} size="sm" />
              {c.name.split(' ')[0]}
            </button>
          ))}
        </div>
      ) : null}

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label={t('dash.childAttendance')} value={`${summary.pct}%`} hint={t('att.recordsCount', { count: summary.total })} icon="calendar" tone={summary.pct >= threshold ? 'leaf' : 'clay'} />
        <StatCard label={t('dash.overallProgress')} value={`${overall}%`} hint={t('marks.bySubject')} icon="chart" tone="brand" />
        <StatCard label={t('dash.upcomingClasses')} value={upcoming.length} hint={upcoming[0] ? formatDate(upcoming[0].date, lang) : t('dash.noUpcoming')} icon="video" tone="saffron" />
        <StatCard label={t('common.notifications')} value={unread.length} hint={t('notif.unread')} icon="bell" tone="ink" />
      </div>

      {summary.pct < threshold && summary.total > 0 ? (
        <Callout tone="danger" title={t('parent.alert')}>
          {t('att.alertBody', { name: child.name.split(' ')[0], pct: summary.pct, threshold })}
        </Callout>
      ) : null}

      <div className="grid gap-4 lg:grid-cols-3">
        <div className="space-y-4 lg:col-span-2">
          <SectionCard title={t('dash.childAttendance')} subtitle={`${child.name} · ${classes.map((c) => c?.name).filter(Boolean).join(', ')}`} icon="calendar" action={<Link to="/attendance" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>}>
            <AttendanceSnapshot summary={summary} label={t('att.thisTerm')} />
            <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
              {[
                { label: t('att.present'), value: summary.present, tone: 'text-leaf-700' },
                { label: t('att.absent'), value: summary.absent, tone: 'text-clay-700' },
                { label: t('att.late'), value: summary.late, tone: 'text-saffron-700' },
                { label: t('att.excused'), value: summary.excused, tone: 'text-ink-600' },
              ].map((s) => (
                <div key={s.label} className="rounded-lg bg-ink-50 p-2 text-center">
                  <p className={`text-lg font-bold tabular-nums ${s.tone}`}>{s.value}</p>
                  <p className="text-[10px] text-ink-500">{s.label}</p>
                </div>
              ))}
            </div>
          </SectionCard>

          <SectionCard title={t('dash.childProgress')} subtitle={t('marks.privacyNote')} icon="chart" action={<Link to="/marks" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>}>
            {results.length ? (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[420px] text-left text-sm">
                  <thead>
                    <tr className="border-b border-ink-200 text-[10px] uppercase tracking-wide text-ink-500">
                      <th className="py-2 pr-2 font-semibold">{t('common.subject')}</th>
                      <th className="py-2 pr-2 font-semibold">{t('marks.assessments')}</th>
                      <th className="py-2 pr-2 text-right font-semibold">{t('common.score')}</th>
                      <th className="py-2 text-right font-semibold">{t('marks.grade')}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-ink-100">
                    {results.slice(0, 5).map(({ mark, assessment }) => (
                      <tr key={mark.id}>
                        <td className="py-2 pr-2"><SubjectChip subjectId={assessment.subjectId} /></td>
                        <td className="py-2 pr-2">
                          <p className="text-xs font-semibold text-ink-800">{assessment.title}</p>
                          <p className="text-[10px] text-ink-500">{formatDate(assessment.date, lang)}</p>
                        </td>
                        <td className="py-2 pr-2 text-right text-xs font-bold tabular-nums">{mark.marks}/{assessment.maxMarks}</td>
                        <td className="py-2 text-right"><Badge tone="brand">{mark.grade}</Badge></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="text-xs text-ink-500">{t('marks.noData')}</p>
            )}
          </SectionCard>

          <SectionCard title={t('dash.upcomingClasses')} icon="video" bodyClassName="space-y-2">
            {upcoming.length ? upcoming.map((s) => {
              const cls = classById(db, s.classId)
              const subject = db.subjects
              return (
                <div key={s.id} className="rounded-xl border border-ink-200 p-3">
                  <div className="flex items-start gap-2.5">
                    <span className="mt-0.5 grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-brand-50 text-brand-700"><Icon name="video" size={16} /></span>
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-bold text-ink-900">{s.title}</p>
                      <p className="mt-0.5 text-[11px] text-ink-500">{cls?.name} · {formatDate(s.date, lang, 'weekday')} · {formatTime(s.startTime, lang)}</p>
                      {s.demoRoom ? <p className="mt-0.5 text-[10px] text-saffron-700">{t('live.demoRoom')}</p> : null}
                    </div>
                  </div>
                </div>
              )
            }) : <p className="text-xs text-ink-500">{t('dash.noUpcoming')}</p>}
            <p className="text-[10px] leading-relaxed text-ink-400">{t('live.linkRestricted')} {t('att.parentHint')}</p>
          </SectionCard>

          <SectionCard title={t('common.announcements')} icon="bell" action={<Link to="/notifications" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>} bodyClassName="space-y-3">
            {announcements.length ? announcements.map((a) => <AnnouncementItem key={a.id} announcement={a} />) : <p className="text-xs text-ink-500">{t('notif.empty')}</p>}
          </SectionCard>
        </div>

        <div className="space-y-4">
          <Card className="p-4">
            <div className="flex items-center gap-3">
              <Avatar name={child.name} color={child.avatarColor} size="lg" />
              <div className="min-w-0">
                <p className="truncate text-sm font-bold text-ink-900">{child.name}</p>
                <p className="text-[11px] text-ink-500">{classes.map((c) => c?.name).filter(Boolean).join(', ')}</p>
                <Badge tone="brand" className="mt-1">{t('classes.rollNo')} {child.rollNo || '—'}</Badge>
              </div>
            </div>
            <p className="mt-3 rounded-lg bg-brand-50 p-2.5 text-[10px] leading-relaxed text-brand-900">
              <Icon name="shield" size={12} className="mr-1 inline" />
              {t('parent.accessNote')}
            </p>
          </Card>

          <SectionCard title={t('marks.subjectProgress')} icon="chart" bodyClassName="space-y-2.5">
            {subjectRows.length ? subjectRows.map((row) => (
              <div key={row.subjectId}>
                <div className="mb-1 flex items-center justify-between text-[11px]">
                  <span className="font-medium text-ink-700">{subjectLabel(row.subjectId, t)}</span>
                  <span className="font-bold tabular-nums text-ink-800">{Math.round(row.pct)}%</span>
                </div>
                <ProgressBar value={row.pct} tone={row.pct >= 75 ? 'leaf' : row.pct >= 50 ? 'brand' : 'saffron'} showValue={false} size="sm" />
              </div>
            )) : <p className="text-xs text-ink-500">{t('marks.noData')}</p>}
          </SectionCard>

          <SectionCard title={t('quiz.submitted')} icon="clipboard" bodyClassName="space-y-2">
            {attempts.length ? attempts.map((a) => {
              const quiz = db.quizzes.find((q) => q.id === a.quizId)
              if (!quiz) return null
              const visible = quizResultsVisible(quiz)
              return (
                <div key={a.id} className="flex items-center justify-between gap-2 rounded-lg px-1.5 py-1.5">
                  <div className="min-w-0">
                    <p className="truncate text-xs font-semibold text-ink-800">{quiz.title}</p>
                    <p className="text-[10px] text-ink-500">{formatDate(a.submittedAt.slice(0, 10), lang)}</p>
                  </div>
                  {visible ? <Badge tone="brand">{a.score}/{a.maxScore}</Badge> : <Badge tone="neutral" icon="lock">{t('marks.notPublished')}</Badge>}
                </div>
              )
            }) : <p className="text-xs text-ink-500">{t('quiz.noAttemptsYet')}</p>}
          </SectionCard>

          <SectionCard title={t('common.notifications')} icon="bell" action={<Link to="/notifications" className="text-xs font-semibold text-brand-700 hover:underline">{t('common.viewAll')}</Link>}>
            <NotificationsPreview items={unread.length ? unread : db.notifications.filter((n) => n.userId === currentUser.id)} />
          </SectionCard>

          <div className="grid grid-cols-2 gap-2">
            <Link to="/attendance" className={buttonClass('secondary', 'sm')}>{t('nav.attendance')}</Link>
            <Link to="/marks" className={buttonClass('secondary', 'sm')}>{t('nav.marks')}</Link>
            <Link to="/scholarships" className={buttonClass('quiet', 'sm')}>{t('nav.scholarships')}</Link>
            <Link to="/feedback" className={buttonClass('quiet', 'sm')}>{t('nav.feedback')}</Link>
          </div>
        </div>
      </div>
    </div>
  )
}

