function ScheduleModal({ open, onClose, classes }: { open: boolean; onClose: () => void; classes: ClassRoom[] }) {
  const { db, currentUser, mutate, notify, toast } = useApp()
  const { t } = useI18n()
  const [title, setTitle] = useState('')
  const [classId, setClassId] = useState(classes[0]?.id || '')
  const [subjectId, setSubjectId] = useState(classes[0]?.subjectIds[0] || 'math')
  const [date, setDate] = useState(todayISO())
  const [startTime, setStartTime] = useState('10:00')
  const [durationMin, setDurationMin] = useState(40)
  const [description, setDescription] = useState('')
  const [materialIds, setMaterialIds] = useState<string[]>([])
  const [demoRoom, setDemoRoom] = useState(true)
  const [zoomLink, setZoomLink] = useState('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  const cls = classById(db, classId)
  const materials = db.resources.filter((r) => r.classId === classId && r.published)

  const submit = () => {
    if (!currentUser) return
    const next: Record<string, string> = {}
    if (title.trim().length < 3) next.title = t('live.required')
    if (!classId) next.classId = t('common.required')
    if (!date || !startTime) next.time = t('live.required')
    if (date < todayISO()) next.time = t('live.datePast')
    if (!demoRoom && zoomLink && !/^https?:\/\//i.test(zoomLink)) next.zoomLink = t('sch.linkInvalid')
    if (Object.keys(next).length) {
      setErrors(next)
      return
    }
    const id = uid('ses')
    mutate((draft) => {
      draft.sessions.push({
        id,
        classId,
        subjectId,
        title: title.trim(),
        description: description.trim() || undefined,
        date,
        startTime,
        durationMin,
        teacherId: currentUser.id,
        status: 'scheduled',
        demoRoom: demoRoom || undefined,
        zoomLink: demoRoom ? `demo://classroom/${id}` : zoomLink.trim() || undefined,
        resourceIds: materialIds,
        recordingIds: [],
        createdAt: new Date().toISOString(),
      })
      for (const student of classStudents(draft, classId)) {
        draft.notifications.unshift({
          id: uid('notif'),
          userId: student.id,
          kind: 'class',
          title: `${t('live.schedule')}: ${title.trim()}`,
          body: `${formatDate(date, 'en')} · ${startTime} · ${currentUser.name}`,
          link: '/live',
          read: false,
          createdAt: new Date().toISOString(),
        })
      }
      draft.audit.unshift({
        id: uid('aud'),
        actorId: currentUser.id,
        actorName: currentUser.name,
        actorRole: currentUser.role,
        action: 'Scheduled live class',
        detail: `${title.trim()} · ${cls?.name || classId}`,
        at: new Date().toISOString(),
      })
    })
    toast('success', t('live.createSuccess'))
    setTitle('')
    setDescription('')
    setMaterialIds([])
    setErrors({})
    onClose()
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={t('live.schedule')}
      description={t('live.teacherSub')}
      size="lg"
      footer={
        <>
          <Button variant="secondary" onClick={onClose}>{t('common.cancel')}</Button>
          <Button onClick={submit} icon="video">{t('live.schedule')}</Button>
        </>
      }
    >
      <div className="space-y-4">
        <Field label={t('live.name')} htmlFor="session-title" required error={errors.title}>
          <TextInput id="session-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder={t('live.name')} invalid={!!errors.title} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('common.class')} htmlFor="session-class" required>
            <Select id="session-class" value={classId} onChange={(e) => { setClassId(e.target.value); setSubjectId(classById(db, e.target.value)?.subjectIds[0] || 'math') }}>
              {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </Field>
          <Field label={t('common.subject')} htmlFor="session-subject" required>
            <Select id="session-subject" value={subjectId} onChange={(e) => setSubjectId(e.target.value)}>
              {(cls?.subjectIds || []).map((s) => <option key={s} value={s}>{subjectLabel(s, t)}</option>)}
            </Select>
          </Field>
        </div>
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label={t('common.date')} htmlFor="session-date" required error={errors.time}>
            <TextInput id="session-date" type="date" value={date} min={todayISO()} onChange={(e) => setDate(e.target.value)} invalid={!!errors.time} />
          </Field>
          <Field label={t('live.startTime')} htmlFor="session-time" required>
            <TextInput id="session-time" type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} />
          </Field>
          <Field label={t('live.duration')} htmlFor="session-duration">
            <Select id="session-duration" value={durationMin} onChange={(e) => setDurationMin(Number(e.target.value))}>
              {[30, 40, 45, 60, 90].map((m) => <option key={m} value={m}>{m} {t('common.minutes')}</option>)}
            </Select>
          </Field>
        </div>
        <Field label={t('live.description')} htmlFor="session-description">
          <TextArea id="session-description" value={description} onChange={(e) => setDescription(e.target.value)} placeholder={t('live.description')} />
        </Field>
        <fieldset>
          <legend className="mb-1.5 text-[13px] font-semibold text-ink-800">{t('live.attachMaterials')}</legend>
          {materials.length ? (
            <div className="max-h-36 space-y-1 overflow-y-auto rounded-xl border border-ink-200 p-2">
              {materials.map((m) => (
                <label key={m.id} className="flex items-start gap-2 rounded-lg p-1.5 hover:bg-ink-50">
                  <input
                    type="checkbox"
                    className="mt-0.5 h-4 w-4 rounded border-ink-300"
                    checked={materialIds.includes(m.id)}
                    onChange={(e) => setMaterialIds((prev) => (e.target.checked ? [...prev, m.id] : prev.filter((x) => x !== m.id)))}
                  />
                  <span className="text-[11px] text-ink-700">{m.title}</span>
                </label>
              ))}
            </div>
          ) : <p className="text-xs text-ink-500">{t('mat.noResults')}</p>}
        </fieldset>

        <div className="rounded-xl border border-saffron-200 bg-saffron-50 p-3">
          <p className="flex items-center gap-1.5 text-xs font-bold text-saffron-900"><Icon name="alert" size={14} /> {t('live.zoomNotConfigured')}</p>
          <p className="mt-1 text-[11px] leading-relaxed text-saffron-800">{t('live.zoomNotConfiguredBody')}</p>
        </div>
        <Toggle checked={demoRoom} onChange={setDemoRoom} label={t('live.useDemoRoom')} description={t('live.demoRoomHint')} />
        {!demoRoom ? (
          <Field label={t('live.pasteLink')} htmlFor="session-link" hint={t('live.joinOpens')} error={errors.zoomLink}>
            <TextInput id="session-link" value={zoomLink} onChange={(e) => setZoomLink(e.target.value)} placeholder="https://…" invalid={!!errors.zoomLink} />
          </Field>
        ) : null}
      </div>
    </Modal>
  )
}

import { useMemo, useState } from 'react'
import { useApp } from '../lib/store'
import { useI18n } from '../lib/i18n'
import { classById, visibleClasses } from '../lib/access'
import { formatDate, formatSize, subjectLabel, todayISO, uid } from '../lib/utils'
import { subjectById } from '../lib/subjects'
import { buildRecordingDownload, recordingPlayable, storageLeftKB } from '../lib/offline'
import type { Lang, Recording } from '../lib/types'
import { Icon } from '../components/Icon'
import { LanguageTags, RecordingAvailability, SubjectChip } from '../components/shared'
import {
  Badge,
  Button,
  Callout,
  Card,
  EmptyState,
  Field,
  Modal,
  PageHeader,
  SectionCard,
  Select,
  TextArea,
  TextInput,
  Toggle,
  buttonClass,
} from '../components/ui'

const LANGS: Array<{ code: Lang; label: string }> = [
  { code: 'en', label: 'English' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'bn', label: 'বাংলা' },
  { code: 'ta', label: 'தமிழ்' },
  { code: 'te', label: 'తెలుగు' },
  { code: 'mr', label: 'मराठी' },
]

export function RecordingsPage() {
  const { db, currentUser, mutate, toast, online } = useApp()
  const { t, lang } = useI18n()
  const [query, setQuery] = useState('')
  const [classFilter, setClassFilter] = useState('all')
  const [subjectFilter, setSubjectFilter] = useState('all')
  const [chapterFilter, setChapterFilter] = useState('all')
  const [teacherFilter, setTeacherFilter] = useState('all')
  const [playing, setPlaying] = useState<Recording | null>(null)
  const [uploadOpen, setUploadOpen] = useState(false)

  if (!currentUser) return null
  const classes = visibleClasses(db, currentUser)
  const classIds = new Set(classes.map((c) => c.id))
  const canManage = currentUser.role === 'teacher' || currentUser.role === 'admin'
  const lowData = !!currentUser.lowDataMode

  const mine = db.recordings.filter((r) => classIds.has(r.classId))
  const chapters = Array.from(new Set(mine.map((r) => r.chapter))).sort()
  const teachers = Array.from(new Set(mine.map((r) => r.teacherId)))
    .map((id) => db.users.find((u) => u.id === id))
    .filter((u): u is NonNullable<typeof u> => !!u)

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return mine
      .filter((r) => classFilter === 'all' || r.classId === classFilter)
      .filter((r) => subjectFilter === 'all' || r.subjectId === subjectFilter)
      .filter((r) => chapterFilter === 'all' || r.chapter === chapterFilter)
      .filter((r) => teacherFilter === 'all' || r.teacherId === teacherFilter)
      .filter((r) => !q || `${r.title} ${r.chapter} ${r.description || ''}`.toLowerCase().includes(q))
      .sort((a, b) => b.date.localeCompare(a.date))
  }, [mine, classFilter, subjectFilter, chapterFilter, teacherFilter, query])

  const download = (recording: Recording) => {
    if (!currentUser) return
    const result = buildRecordingDownload(db, currentUser.id, recording)
    if (!result.ok) {
      if (result.error === 'exists') toast('info', t('common.downloaded'), recording.title)
      else if (result.error === 'no-space') toast('error', t('dl.noSpace'), `${storageLeftKB(db, currentUser.id)} KB ${t('common.download').toLowerCase()} left`)
      else toast('error', t('rec.downloadDisabled'), recording.title)
      return
    }
    mutate((draft) => {
      draft.downloads.push(result.download)
      draft.activity.push({
        id: uid('act'),
        studentId: currentUser.id,
        classId: recording.classId,
        points: 2,
        reason: 'download-recording',
        at: new Date().toISOString(),
      })
    })
    toast('success', t('dl.offlineReady'), `${recording.title} · ${formatSize(recording.sizeMB * 1024)}`)
  }

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('rec.title')}
        subtitle={t('rec.sub')}
        icon="play"
        actions={canManage ? <Button icon="upload" onClick={() => setUploadOpen(true)}>{t('rec.upload')}</Button> : null}
      />

      {lowData ? <Callout tone="success" icon="leaf" title={t('shell.lowDataOn')}>{t('rec.lowDataNote')}</Callout> : null}
      {!online ? <Callout tone="warn" title={t('state.offlineTitle')}>{t('rec.playUnavailable')}</Callout> : null}

      <SectionCard icon="filter" bodyClassName="space-y-3">
        <div className="relative">
          <Icon name="search" size={16} className="pointer-events-none absolute left-3 top-3 text-ink-400" />
          <TextInput value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t('rec.search')} className="pl-9" aria-label={t('rec.search')} />
        </div>
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
          <Select value={classFilter} onChange={(e) => setClassFilter(e.target.value)} aria-label={t('rec.allClasses')}>
            <option value="all">{t('rec.allClasses')}</option>
            {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </Select>
          <Select value={subjectFilter} onChange={(e) => setSubjectFilter(e.target.value)} aria-label={t('rec.allSubjects')}>
            <option value="all">{t('rec.allSubjects')}</option>
            {Array.from(new Set(mine.map((r) => r.subjectId))).map((s) => <option key={s} value={s}>{subjectLabel(s, t)}</option>)}
          </Select>
          <Select value={chapterFilter} onChange={(e) => setChapterFilter(e.target.value)} aria-label={t('rec.allChapters')}>
            <option value="all">{t('rec.allChapters')}</option>
            {chapters.map((c) => <option key={c} value={c}>{c}</option>)}
          </Select>
          <Select value={teacherFilter} onChange={(e) => setTeacherFilter(e.target.value)} aria-label={t('rec.allTeachers')}>
            <option value="all">{t('rec.allTeachers')}</option>
            {teachers.map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}
          </Select>
        </div>
        <p className="text-[10px] text-ink-400">{t('rec.teacherHint')} · {filtered.length} {t('common.results').toLowerCase()}</p>
      </SectionCard>

      {filtered.length ? (
        <div className="grid gap-3 lg:grid-cols-2">
          {filtered.map((r) => {
            const cls = classById(db, r.classId)
            const teacher = db.users.find((u) => u.id === r.teacherId)
            const downloadable = r.downloadEnabled
            const downloaded = db.downloads.some((d) => d.userId === currentUser.id && d.kind === 'recording' && d.refId === r.id)
            return (
              <Card key={r.id} className="p-4">
                <div className="flex items-start gap-3">
                  <button
                    type="button"
                    onClick={() => setPlaying(r)}
                    className="relative grid h-16 w-24 shrink-0 place-items-center overflow-hidden rounded-lg bg-ink-800 text-white hover:bg-ink-700"
                    aria-label={`${t('rec.watch')}: ${r.title}`}
                  >
                    <Icon name={recordingPlayable(r) ? 'play' : 'video'} size={22} className={recordingPlayable(r) ? '' : 'opacity-50'} />
                    <span className="absolute bottom-0.5 right-1 rounded bg-black/50 px-1 text-[9px] font-semibold">{r.durationMin}m</span>
                  </button>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-1.5">
                      <RecordingAvailability recording={r} />
                      <SubjectChip subjectId={r.subjectId} />
                      {lowData ? <Badge tone="leaf" icon="leaf">{t('shell.lowData')}</Badge> : null}
                    </div>
                    <h3 className="mt-1 text-sm font-bold leading-snug text-ink-900">{r.title}</h3>
                    <p className="mt-0.5 text-xs text-ink-500">{cls?.name} · {teacher?.name} · {formatDate(r.date, lang)}</p>
                    <p className="text-[11px] text-ink-500">{r.chapter} · <LanguageTags languages={[r.language]} /></p>
                    {r.description ? <p className="mt-1 line-clamp-2 text-[11px] leading-relaxed text-ink-600">{r.description}</p> : null}
                    <p className="mt-1 text-[10px] text-ink-400">{formatSize(r.sizeMB * 1024)} · {r.source === 'zoom' ? t('rec.sourceZoom') : t('rec.sourceUpload')}</p>
                  </div>
                </div>
                <div className="mt-3 flex flex-wrap gap-2 border-t border-ink-100 pt-3">
                  <Button size="sm" variant={recordingPlayable(r) ? 'primary' : 'secondary'} icon="play" onClick={() => setPlaying(r)}>
                    {recordingPlayable(r) ? t('rec.watch') : t('common.open')}
                  </Button>
                  {downloadable ? (
                    <Button size="sm" variant={downloaded ? 'quiet' : 'secondary'} icon="download" onClick={() => download(r)} disabled={downloaded}>
                      {downloaded ? t('common.downloaded') : t('rec.download')}
                    </Button>
                  ) : (
                    <span className="inline-flex items-center gap-1 text-[10px] text-ink-500"><Icon name="lock" size={12} /> {t('rec.downloadsOff')}</span>
                  )}
                  <span className="ml-auto self-center text-[10px] text-ink-400">{t('rec.sizeBefore', { size: formatSize(r.sizeMB * 1024) })}</span>
                </div>
              </Card>
            )
          })}
        </div>
      ) : (
        <EmptyState icon="play" title={t('rec.noResults')} description={t('rec.sub')} action={<Button variant="secondary" size="sm" onClick={() => { setQuery(''); setClassFilter('all'); setSubjectFilter('all'); setChapterFilter('all'); setTeacherFilter('all') }}>{t('common.filters')}</Button>} />
      )}

      <Callout tone="info" title={t('rec.playUnavailableTitle')}>{t('rec.playUnavailableBody')}</Callout>

      {canManage ? <UploadRecordingModal open={uploadOpen} onClose={() => setUploadOpen(false)} /> : null}
      <PlayerModal recording={playing} onClose={() => setPlaying(null)} />
    </div>
  )
}

function PlayerModal({ recording, onClose }: { recording: Recording | null; onClose: () => void }) {
  const { t, lang } = useI18n()
  if (!recording) return null
  const playable = recordingPlayable(recording)
  return (
    <Modal open onClose={onClose} title={recording.title} description={`${recording.chapter} · ${formatDate(recording.date, lang)}`} size="lg">
      <div className="space-y-3">
        {playable ? (
          <video controls preload="metadata" className="w-full rounded-xl bg-black" aria-label={recording.title}>
            <source src={recording.mediaUrl} type="video/mp4" />
            Your browser does not support video playback.
          </video>
        ) : (
          <div className="rounded-xl border border-saffron-200 bg-saffron-50 p-5 text-center">
            <Icon name="video" size={32} className="mx-auto text-saffron-600" />
            <p className="mt-2 font-bold text-saffron-900">{t('rec.playUnavailableTitle')}</p>
            <p className="mx-auto mt-1 max-w-md text-xs leading-relaxed text-saffron-800">{t('rec.playUnavailableBody')}</p>
          </div>
        )}
        {recording.mediaUrl ? (
          <div className="rounded-lg bg-brand-50 p-2.5 text-[10px] leading-relaxed text-brand-900">
            <Icon name="info" size={12} className="mr-1 inline" />
            Demonstration clip. {recording.description}
          </div>
        ) : null}
        <div className="grid gap-2 sm:grid-cols-2">
          <div className="rounded-xl border border-ink-200 p-3">
            <p className="text-[10px] font-semibold uppercase tracking-wide text-ink-400">{t('common.language')}</p>
            <p className="mt-0.5 text-xs text-ink-800"><LanguageTags languages={[recording.language]} /></p>
          </div>
          <div className="rounded-xl border border-ink-200 p-3">
            <p className="text-[10px] font-semibold uppercase tracking-wide text-ink-400">{t('common.size')}</p>
            <p className="mt-0.5 text-xs text-ink-800">{formatSize(recording.sizeMB * 1024)} · {recording.durationMin} {t('common.minutes')}</p>
          </div>
        </div>
        <p className="text-[10px] text-ink-400">{t('dl.requiresOnline')}</p>
      </div>
    </Modal>
  )
}

function UploadRecordingModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { db, currentUser, mutate, toast } = useApp()
  const { t } = useI18n()
  const classes = currentUser ? visibleClasses(db, currentUser) : []
  const [title, setTitle] = useState('')
  const [classId, setClassId] = useState(classes[0]?.id || '')
  const [subjectId, setSubjectId] = useState(classes[0]?.subjectIds[0] || 'math')
  const [chapter, setChapter] = useState('')
  const [date, setDate] = useState(todayISO())
  const [durationMin, setDurationMin] = useState(35)
  const [sizeMB, setSizeMB] = useState(40)
  const [mediaUrl, setMediaUrl] = useState('')
  const [description, setDescription] = useState('')
  const [language, setLanguage] = useState<Lang>('en')
  const [downloadEnabled, setDownloadEnabled] = useState(true)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const submit = () => {
    if (!currentUser) return
    const next: Record<string, string> = {}
    if (title.trim().length < 3) next.title = t('live.required')
    if (!classId || !chapter.trim()) next.chapter = t('common.required')
    if (mediaUrl && !/^https?:\/\//i.test(mediaUrl)) next.mediaUrl = t('sch.linkInvalid')
    if (Object.keys(next).length) {
      setErrors(next)
      return
    }
    mutate((draft) => {
      draft.recordings.unshift({
        id: uid('rec'),
        classId,
        subjectId,
        title: title.trim(),
        chapter: chapter.trim(),
        teacherId: currentUser.id,
        date,
        durationMin,
        sizeMB,
        mediaUrl: mediaUrl.trim() || undefined,
        downloadEnabled,
        source: mediaUrl.trim() ? 'upload' : 'zoom',
        description: description.trim() || undefined,
        language,
        status: mediaUrl.trim() ? 'ready' : 'processing',
      })
      for (const student of draft.users.filter((u) => u.role === 'student' && draft.enrollments.some((e) => e.classId === classId && e.studentId === u.id && e.status === 'active'))) {
        draft.notifications.unshift({
          id: uid('notif'),
          userId: student.id,
          kind: 'class',
          title: `${t('rec.recent')}: ${title.trim()}`,
          body: `${t('common.class')}: ${db.classes.find((c) => c.id === classId)?.name || ''}`,
          link: '/recordings',
          read: false,
          createdAt: new Date().toISOString(),
        })
      }
    })
    toast('success', t('rec.added'), mediaUrl.trim() ? undefined : t('rec.playUnavailableTitle'))
    setTitle('')
    setChapter('')
    setDescription('')
    setMediaUrl('')
    setErrors({})
    onClose()
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={t('rec.upload')}
      description={t('rec.mediaNote')}
      footer={<><Button variant="secondary" onClick={onClose}>{t('common.cancel')}</Button><Button onClick={submit} icon="upload">{t('common.add')}</Button></>}
    >
      <div className="space-y-3.5">
        <Field label={t('live.name')} htmlFor="rec-title" required error={errors.title}>
          <TextInput id="rec-title" value={title} onChange={(e) => setTitle(e.target.value)} invalid={!!errors.title} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('common.class')} htmlFor="rec-class" required>
            <Select id="rec-class" value={classId} onChange={(e) => { setClassId(e.target.value); setSubjectId(classById(db, e.target.value)?.subjectIds[0] || 'math') }}>
              {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </Field>
          <Field label={t('common.subject')} htmlFor="rec-subject" required>
            <Select id="rec-subject" value={subjectId} onChange={(e) => setSubjectId(e.target.value)}>
              {(classById(db, classId)?.subjectIds || []).map((s) => <option key={s} value={s}>{subjectLabel(s, t)}</option>)}
            </Select>
          </Field>
        </div>
        <Field label={t('common.chapter')} htmlFor="rec-chapter" required error={errors.chapter}>
          <TextInput id="rec-chapter" value={chapter} onChange={(e) => setChapter(e.target.value)} invalid={!!errors.chapter} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label={t('common.date')} htmlFor="rec-date">
            <TextInput id="rec-date" type="date" value={date} onChange={(e) => setDate(e.target.value)} />
          </Field>
          <Field label={t('live.duration')} htmlFor="rec-duration">
            <TextInput id="rec-duration" type="number" min={1} value={durationMin} onChange={(e) => setDurationMin(Number(e.target.value))} />
          </Field>
          <Field label={t('common.size')} htmlFor="rec-size">
            <TextInput id="rec-size" type="number" min={1} value={sizeMB} onChange={(e) => setSizeMB(Number(e.target.value))} />
          </Field>
        </div>
        <Field label={t('live.recordingLink')} htmlFor="rec-url" hint={t('rec.mediaNote')} error={errors.mediaUrl}>
          <TextInput id="rec-url" value={mediaUrl} onChange={(e) => setMediaUrl(e.target.value)} placeholder="https://…" invalid={!!errors.mediaUrl} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('common.language')} htmlFor="rec-lang">
            <Select id="rec-lang" value={language} onChange={(e) => setLanguage(e.target.value as Lang)}>
              {LANGS.map((l) => <option key={l.code} value={l.code}>{l.label}</option>)}
            </Select>
          </Field>
          <div className="pt-6"><Toggle checked={downloadEnabled} onChange={setDownloadEnabled} label={t('rec.downloadsOn')} description={t('rec.mediaNote')} /></div>
        </div>
        <Field label={t('common.note')} htmlFor="rec-desc">
          <TextArea id="rec-desc" value={description} onChange={(e) => setDescription(e.target.value)} />
        </Field>
        <p className="text-[10px] leading-relaxed text-ink-400">{t('rec.mediaNote')}</p>
      </div>
    </Modal>
  )
}

import { useMemo, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useApp } from '../lib/store'
import { useI18n, LANG_OPTIONS, CONTENT_LANG_LABEL } from '../lib/i18n'
import { classById, visibleClasses } from '../lib/access'
import { RESOURCE_TYPE_LABEL } from '../lib/subjects'
import { formatDate, formatSize, subjectLabel, uid } from '../lib/utils'
import { buildResourceDownload, DEMO_STORAGE_LIMIT_KB, storageUsedKB } from '../lib/offline'
import type { Lang, Resource, ResourceType } from '../lib/types'
import { Icon } from '../components/Icon'
import { LanguageTags, ResourceTypeBadge, SubjectChip } from '../components/shared'
import {
  Badge,
  Button,
  Callout,
  Card,
  EmptyState,
  Field,
  Modal,
  PageHeader,
  ProgressBar,
  SectionCard,
  Select,
  TextArea,
  TextInput,
  Toggle,
  buttonClass,
} from '../components/ui'

const TYPES: ResourceType[] = ['note', 'textbook', 'question-paper', 'mcq-set', 'fill-blanks', 'revision', 'storybook', 'supplementary']

export function MaterialsPage() {
  const { db, currentUser, mutate, toast } = useApp()
  const { t, lang } = useI18n()
  const [params] = useSearchParams()
  const [query, setQuery] = useState('')
  const [classFilter, setClassFilter] = useState('all')
  const [subjectFilter, setSubjectFilter] = useState('all')
  const [typeFilter, setTypeFilter] = useState('all')
  const [langFilter, setLangFilter] = useState('all')
  const [reading, setReading] = useState<Resource | null>(null)
  const [editing, setEditing] = useState<Resource | null>(null)
  const [uploadOpen, setUploadOpen] = useState(params.get('upload') === '1')

  if (!currentUser) return null
  const classes = visibleClasses(db, currentUser)
  const classIds = new Set(classes.map((c) => c.id))
  const canManage = currentUser.role === 'teacher' || currentUser.role === 'admin'
  const isStudent = currentUser.role === 'student'

  const base = db.resources.filter((r) => classIds.has(r.classId) && (canManage || r.published))
  const chapters = Array.from(new Set(base.map((r) => r.chapter))).sort()

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return base
      .filter((r) => classFilter === 'all' || r.classId === classFilter)
      .filter((r) => subjectFilter === 'all' || r.subjectId === subjectFilter)
      .filter((r) => typeFilter === 'all' || r.type === typeFilter)
      .filter((r) => langFilter === 'all' || r.languages.includes(langFilter as Lang))
      .filter((r) => !q || `${r.title} ${r.chapter} ${r.topics.join(' ')} ${r.description}`.toLowerCase().includes(q))
      .sort((a, b) => Number(b.published) - Number(a.published) || b.uploadedAt.localeCompare(a.uploadedAt))
  }, [base, classFilter, subjectFilter, typeFilter, langFilter, query])

  const download = (resource: Resource) => {
    if (!currentUser) return
    const result = buildResourceDownload(db, currentUser.id, resource)
    if (!result.ok) {
      if (result.error === 'exists') toast('info', t('common.downloaded'), resource.title)
      else if (result.error === 'no-space') toast('error', t('dl.noSpace'), t('dl.storageNote'))
      else toast('error', t('mat.previewOnly'))
      return
    }
    mutate((draft) => {
      draft.downloads.push(result.download)
      draft.activity.push({ id: uid('act'), studentId: currentUser.id, classId: resource.classId, points: 2, reason: 'download-resource', at: new Date().toISOString() })
      if (draft.downloads.filter((d) => d.userId === currentUser.id).length >= 2 && !draft.userBadges.some((b) => b.userId === currentUser.id && b.badgeKey === 'offlineLearner')) {
        draft.userBadges.push({ id: uid('ub'), userId: currentUser.id, badgeKey: 'offlineLearner', awardedAt: new Date().toISOString() })
      }
    })
    toast('success', t('mat.downloadStarted'), `${resource.title} · ${formatSize(resource.sizeKB)}`)
  }

  const bookmark = (resource: Resource) => {
    if (!currentUser || !isStudent) return
    const existing = db.bookmarks.find((b) => b.userId === currentUser.id && b.resourceId === resource.id)
    mutate((draft) => {
      if (existing) draft.bookmarks = draft.bookmarks.filter((b) => b.id !== existing.id)
      else draft.bookmarks.push({ id: uid('bm'), userId: currentUser.id, resourceId: resource.id, addedAt: new Date().toISOString() })
      if (draft.bookmarks.filter((b) => b.userId === currentUser.id).length >= 3 && !draft.userBadges.some((b) => b.userId === currentUser.id && b.badgeKey === 'bookworm')) {
        draft.userBadges.push({ id: uid('ub'), userId: currentUser.id, badgeKey: 'bookworm', awardedAt: new Date().toISOString() })
      }
    })
    toast('success', existing ? t('lib.removedFromLibrary') : t('mat.bookmarked'))
  }

  const togglePublish = (resource: Resource) => {
    mutate((draft) => {
      const r = draft.resources.find((x) => x.id === resource.id)
      if (r) r.published = !r.published
    })
    toast('success', resource.published ? t('mat.unpublished') : t('mat.publishedToast'))
  }

  const remove = (resource: Resource) => {
    if (!window.confirm(t('mat.removeConfirm'))) return
    mutate((draft) => {
      draft.resources = draft.resources.filter((r) => r.id !== resource.id)
      draft.bookmarks = draft.bookmarks.filter((b) => b.resourceId !== resource.id)
      draft.downloads = draft.downloads.filter((d) => !(d.kind === 'resource' && d.refId === resource.id))
    })
    toast('success', t('mat.deleted'))
  }

  const used = currentUser ? storageUsedKB(db, currentUser.id) : 0

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('mat.title')}
        subtitle={canManage ? t('mat.teacherSub') : t('mat.sub')}
        icon="book"
        actions={canManage ? <Button icon="upload" onClick={() => setUploadOpen(true)}>{t('mat.upload')}</Button> : <a href="#downloads" className={buttonClass('secondary', 'md')}><Icon name="download" size={17} /> {t('nav.downloads')}</a>}
      />

      {canManage ? <Callout tone="info" title={t('mat.studentsSee')}>{t('mat.teacherNote')}</Callout> : null}

      <SectionCard icon="filter" bodyClassName="space-y-3">
        <div className="relative">
          <Icon name="search" size={16} className="pointer-events-none absolute left-3 top-3 text-ink-400" />
          <TextInput value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t('mat.search')} className="pl-9" aria-label={t('mat.search')} />
        </div>
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
          <Select value={classFilter} onChange={(e) => setClassFilter(e.target.value)} aria-label={t('mat.classFilter')}>
            <option value="all">{t('common.all')} {t('common.class').toLowerCase()}es</option>
            {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </Select>
          <Select value={subjectFilter} onChange={(e) => setSubjectFilter(e.target.value)} aria-label={t('mat.subjectFilter')}>
            <option value="all">{t('common.all')} {t('common.subject').toLowerCase()}s</option>
            {Array.from(new Set(base.map((r) => r.subjectId))).map((s) => <option key={s} value={s}>{subjectLabel(s, t)}</option>)}
          </Select>
          <Select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)} aria-label={t('mat.type')}>
            <option value="all">{t('common.all')} {t('common.type').toLowerCase()}s</option>
            {TYPES.map((ty) => <option key={ty} value={ty}>{t(RESOURCE_TYPE_LABEL[ty])}</option>)}
          </Select>
          <Select value={langFilter} onChange={(e) => setLangFilter(e.target.value)} aria-label={t('mat.languageFilter')}>
            <option value="all">{t('common.all')} {t('common.language').toLowerCase()}s</option>
            {LANG_OPTIONS.map((code) => <option key={code} value={code}>{CONTENT_LANG_LABEL[code]}</option>)}
          </Select>
        </div>
        <div className="flex flex-wrap items-center gap-2 text-[10px] text-ink-400">
          <span>{filtered.length} {t('common.results').toLowerCase()}</span>
          <span>·</span>
          <span>{chapters.length} {t('common.chapter').toLowerCase()}s</span>
          {langFilter !== 'all' ? <Badge tone="brand">{CONTENT_LANG_LABEL[langFilter as Lang]}</Badge> : null}
        </div>
      </SectionCard>

      {filtered.length ? (
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {filtered.map((r) => {
            const cls = classById(db, r.classId)
            const bookmarked = db.bookmarks.some((b) => b.userId === currentUser.id && b.resourceId === r.id)
            const downloaded = db.downloads.some((d) => d.userId === currentUser.id && d.kind === 'resource' && d.refId === r.id)
            return (
              <Card key={r.id} className="flex flex-col p-4">
                <div className="flex flex-wrap items-center gap-1.5">
                  <ResourceTypeBadge type={r.type} />
                  <SubjectChip subjectId={r.subjectId} />
                  {!r.published ? <Badge tone="neutral" icon="edit">{t('common.draft')}</Badge> : null}
                </div>
                <h3 className="mt-2 text-sm font-bold leading-snug text-ink-900">{r.title}</h3>
                <p className="mt-0.5 text-[11px] text-ink-500">{cls?.name} · {r.chapter}</p>
                <p className="mt-1 line-clamp-2 text-[11px] leading-relaxed text-ink-600">{r.description}</p>
                <div className="mt-2 flex flex-wrap items-center gap-1.5">
                  <LanguageTags languages={r.languages} />
                  {r.downloadable ? <Badge tone="leaf" icon="download">{formatSize(r.sizeKB)}</Badge> : <Badge tone="neutral" icon="lock">{t('mat.previewOnly')}</Badge>}
                  {r.pages ? <span className="text-[10px] text-ink-400">{t('mat.pages', { count: r.pages })}</span> : null}
                </div>
                <div className="mt-auto flex flex-wrap gap-1.5 pt-3">
                  <Button size="sm" icon="book" onClick={() => setReading(r)}>{r.content ? t('mat.reader') : t('common.open')}</Button>
                  {!canManage && r.downloadable ? (
                    <Button size="sm" variant={downloaded ? 'quiet' : 'secondary'} icon="download" onClick={() => download(r)} disabled={downloaded}>
                      {downloaded ? t('common.downloaded') : t('common.download')}
                    </Button>
                  ) : null}
                  {isStudent ? (
                    <Button size="sm" variant="ghost" icon="bookmark" onClick={() => bookmark(r)} aria-pressed={bookmarked} className={bookmarked ? 'text-brand-700' : ''}>
                      {bookmarked ? t('lib.bookmarked') : t('lib.bookmark')}
                    </Button>
                  ) : null}
                  {canManage ? (
                    <>
                      <Button size="sm" variant="ghost" icon="edit" onClick={() => setEditing(r)}>{t('common.edit')}</Button>
                      <Button size="sm" variant="ghost" onClick={() => togglePublish(r)}>{r.published ? t('common.unpublish') : t('common.publish')}</Button>
                      <Button size="sm" variant="ghost" onClick={() => remove(r)} aria-label={t('common.delete')}><Icon name="trash" size={14} /></Button>
                    </>
                  ) : null}
                </div>
              </Card>
            )
          })}
        </div>
      ) : (
        <EmptyState icon="book" title={t('mat.noResults')} description={t('mat.filterHint')} />
      )}

      <section id="downloads" className="scroll-mt-24 grid gap-3 sm:grid-cols-[1fr_auto] sm:items-center">
        <Card className="p-4">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="flex items-center gap-1.5 text-sm font-bold text-ink-900"><Icon name="download" size={16} className="text-brand-600" /> {t('dl.title')}</p>
              <p className="mt-0.5 text-[11px] text-ink-500">{t('dl.storageNote')}</p>
            </div>
            <Badge tone="brand">{formatSize(used)} / {formatSize(DEMO_STORAGE_LIMIT_KB)}</Badge>
          </div>
          <div className="mt-2"><ProgressBar value={(used / DEMO_STORAGE_LIMIT_KB) * 100} tone={used / DEMO_STORAGE_LIMIT_KB > 0.8 ? 'clay' : 'brand'} showValue={false} size="sm" /></div>
          <p className="mt-2 text-[10px] text-ink-400">{t('dl.requiresOnline')}</p>
        </Card>
        <a href="/downloads" className={buttonClass('secondary', 'md')}>{t('dl.title')} <Icon name="chevronRight" size={16} /></a>
      </section>

      <ReaderModal resource={reading} onClose={() => setReading(null)} onDownload={download} onBookmark={bookmark} isStudent={isStudent} />
      {canManage ? <ResourceFormModal open={uploadOpen} onClose={() => setUploadOpen(false)} classes={classes} /> : null}
      {canManage ? <ResourceFormModal open={!!editing} onClose={() => setEditing(null)} classes={classes} resource={editing} /> : null}
    </div>
  )
}

function ReaderModal({
  resource,
  onClose,
  onDownload,
  onBookmark,
  isStudent,
}: {
  resource: Resource | null
  onClose: () => void
  onDownload: (r: Resource) => void
  onBookmark: (r: Resource) => void
  isStudent: boolean
}) {
  const { db, currentUser } = useApp()
  const { t, lang } = useI18n()
  if (!resource) return null
  const downloaded = !!currentUser && db.downloads.some((d) => d.userId === currentUser.id && d.kind === 'resource' && d.refId === resource.id)
  const bookmarked = !!currentUser && db.bookmarks.some((b) => b.userId === currentUser.id && b.resourceId === resource.id)
  return (
    <Modal
      open
      onClose={onClose}
      title={resource.title}
      description={`${resource.chapter} · ${resource.languages.map((l) => CONTENT_LANG_LABEL[l]).join(', ')}`}
      size="lg"
      footer={
        <>
          {isStudent ? (
            <Button variant="ghost" icon="bookmark" onClick={() => onBookmark(resource)} className="mr-auto">
              {bookmarked ? t('lib.removeBookmark') : t('mat.bookmark')}
            </Button>
          ) : null}
          {resource.downloadable ? (
            <Button variant="secondary" icon="download" onClick={() => onDownload(resource)} disabled={downloaded}>
              {downloaded ? t('common.downloaded') : t('common.download')}
            </Button>
          ) : null}
          <Button onClick={onClose}>{t('common.close')}</Button>
        </>
      }
    >
      {resource.content ? (
        <article className="notes-body">{resource.content}</article>
      ) : (
        <div className="rounded-xl border border-ink-200 bg-ink-50 p-5 text-center">
          <Icon name="file" size={30} className="mx-auto text-ink-400" />
          <p className="mt-2 text-sm font-semibold text-ink-800">{t('mat.noContent')}</p>
          {resource.fileUrl ? (
            <a href={resource.fileUrl} target="_blank" rel="noreferrer" className={buttonClass('secondary', 'sm', 'mt-3')}>
              {t('common.open')} <Icon name="external" size={14} />
            </a>
          ) : null}
        </div>
      )}
      <div className="mt-4 flex flex-wrap items-center gap-2 border-t border-ink-100 pt-3">
        <Badge tone="brand" icon="file">{t(RESOURCE_TYPE_LABEL[resource.type])}</Badge>
        <span className="text-[10px] text-ink-400">{formatSize(resource.sizeKB)} · {formatDate(resource.uploadedAt.slice(0, 10), lang)}</span>
        {resource.content ? <Badge tone="leaf" icon="checkCircle">{t('common.availableOffline')}</Badge> : <Badge tone="neutral" icon="cloud">{t('common.requiresInternet')}</Badge>}
      </div>
    </Modal>
  )
}

function ResourceFormModal({
  open,
  onClose,
  classes,
  resource,
}: {
  open: boolean
  onClose: () => void
  classes: ReturnType<typeof visibleClasses>
  resource?: Resource | null
}) {
  const { db, currentUser, mutate, toast } = useApp()
  const { t } = useI18n()
  const [title, setTitle] = useState(resource?.title || '')
  const [classId, setClassId] = useState(resource?.classId || classes[0]?.id || '')
  const [subjectId, setSubjectId] = useState(resource?.subjectId || classes[0]?.subjectIds[0] || 'math')
  const [type, setType] = useState<ResourceType>(resource?.type || 'note')
  const [chapter, setChapter] = useState(resource?.chapter || '')
  const [description, setDescription] = useState(resource?.description || '')
  const [content, setContent] = useState(resource?.content || '')
  const [sizeKB, setSizeKB] = useState(resource?.sizeKB || 300)
  const [pages, setPages] = useState(resource?.pages || 4)
  const [languages, setLanguages] = useState<Lang[]>(resource?.languages || ['en'])
  const [downloadable, setDownloadable] = useState(resource?.downloadable ?? true)
  const [published, setPublished] = useState(resource?.published ?? true)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const submit = () => {
    if (!currentUser) return
    const next: Record<string, string> = {}
    if (title.trim().length < 3 || !classId || !subjectId) next.required = t('mat.required')
    if (languages.length === 0) next.languages = t('common.required')
    if (Object.keys(next).length) {
      setErrors(next)
      return
    }
    const payload: Resource = {
      id: resource?.id || uid('res'),
      title: title.trim(),
      description: description.trim(),
      type,
      classId,
      subjectId,
      chapter: chapter.trim() || t('common.chapter'),
      topics: resource?.topics || [chapter.trim() || 'general'],
      languages,
      sizeKB,
      downloadable,
      published,
      uploadedBy: resource?.uploadedBy || currentUser.id,
      uploadedAt: resource?.uploadedAt || new Date().toISOString(),
      content: content.trim() || undefined,
      pages,
      gradeLevels: resource?.gradeLevels || [classById(db, classId)?.gradeLevel || 8],
    }
    mutate((draft) => {
      if (resource) {
        const idx = draft.resources.findIndex((r) => r.id === resource.id)
        if (idx >= 0) draft.resources[idx] = payload
      } else {
        draft.resources.unshift(payload)
      }
      draft.audit.unshift({
        id: uid('aud'),
        actorId: currentUser.id,
        actorName: currentUser.name,
        actorRole: currentUser.role,
        action: resource ? 'Updated resource' : 'Added resource',
        detail: payload.title,
        at: new Date().toISOString(),
      })
    })
    toast('success', resource ? t('mat.saved') : t('mat.publishedToast'), payload.title)
    setErrors({})
    onClose()
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={resource ? t('mat.editTitle') : t('mat.uploadTitle')}
      description={t('mat.contentHint')}
      size="lg"
      footer={<><Button variant="secondary" onClick={onClose}>{t('common.cancel')}</Button><Button onClick={submit} icon="check">{resource ? t('common.saveChanges') : t('common.create')}</Button></>}
    >
      <div className="space-y-3.5">
        {errors.required ? <Callout tone="danger" title={errors.required} /> : null}
        <Field label={t('mat.name')} htmlFor="res-title" required>
          <TextInput id="res-title" value={title} onChange={(e) => setTitle(e.target.value)} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label={t('common.class')} htmlFor="res-class" required>
            <Select id="res-class" value={classId} onChange={(e) => { setClassId(e.target.value); setSubjectId(classById(db, e.target.value)?.subjectIds[0] || 'math') }}>
              {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </Field>
          <Field label={t('common.subject')} htmlFor="res-subject" required>
            <Select id="res-subject" value={subjectId} onChange={(e) => setSubjectId(e.target.value)}>
              {(classById(db, classId)?.subjectIds || []).map((s) => <option key={s} value={s}>{subjectLabel(s, t)}</option>)}
            </Select>
          </Field>
          <Field label={t('mat.type')} htmlFor="res-type">
            <Select id="res-type" value={type} onChange={(e) => setType(e.target.value as ResourceType)}>
              {TYPES.map((ty) => <option key={ty} value={ty}>{t(RESOURCE_TYPE_LABEL[ty])}</option>)}
            </Select>
          </Field>
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('mat.chapterName')} htmlFor="res-chapter">
            <TextInput id="res-chapter" value={chapter} onChange={(e) => setChapter(e.target.value)} />
          </Field>
          <Field label={t('mat.size')} htmlFor="res-size">
            <TextInput id="res-size" type="number" min={1} value={sizeKB} onChange={(e) => setSizeKB(Number(e.target.value))} />
          </Field>
        </div>
        <Field label={t('mat.description')} htmlFor="res-desc">
          <TextInput id="res-desc" value={description} onChange={(e) => setDescription(e.target.value)} />
        </Field>
        <Field label={t('mat.content')} htmlFor="res-content" hint={t('mat.contentHint')}>
          <TextArea id="res-content" value={content} onChange={(e) => setContent(e.target.value)} className="min-h-[160px] font-mono text-xs" />
        </Field>
        <fieldset>
          <legend className="mb-1.5 text-[13px] font-semibold text-ink-800">{t('mat.languages')}</legend>
          <div className="flex flex-wrap gap-2">
            {LANG_OPTIONS.map((code) => {
              const active = languages.includes(code)
              return (
                <button
                  key={code}
                  type="button"
                  aria-pressed={active}
                  onClick={() => setLanguages((prev) => (active ? prev.filter((x) => x !== code) : [...prev, code]))}
                  className={`min-h-9 rounded-full border px-3 text-xs font-medium ${active ? 'border-brand-600 bg-brand-600 text-white' : 'border-ink-200 text-ink-700 hover:bg-ink-50'}`}
                >
                  {CONTENT_LANG_LABEL[code]}
                </button>
              )
            })}
          </div>
        </fieldset>
        <div className="grid gap-3 sm:grid-cols-2">
          <Toggle checked={downloadable} onChange={setDownloadable} label={t('mat.downloadable')} description={t('mat.teacherNote')} />
          <Toggle checked={published} onChange={setPublished} label={t('mat.publishNow')} description={t('mat.studentsSee')} />
        </div>
        <p className="text-[10px] text-ink-400">{t('mat.teacherNote')}</p>
      </div>
    </Modal>
  )
}

import { useMemo, useState } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import { useApp } from '../lib/store'
import { useI18n } from '../lib/i18n'
import {
  attemptsForQuiz,
  openQuizzesFor,
  quizMaxScore,
  quizResultsVisible,
  studentClassIds,
  visibleClasses,
} from '../lib/access'
import { formatDate, subjectLabel, todayISO, uid } from '../lib/utils'
import type { Question, Quiz } from '../lib/types'
import { Icon } from '../components/Icon'
import { QuizRow, SubjectChip } from '../components/shared'
import {
  Badge,
  Button,
  Callout,
  Checkbox,
  EmptyState,
  Field,
  Modal,
  PageHeader,
  SectionCard,
  Select,
  Tabs,
  TextArea,
  TextInput,
  Toggle,
  buttonClass,
} from '../components/ui'

export function QuizzesPage() {
  const { db, currentUser, mutate, toast } = useApp()
  const { t, lang } = useI18n()
  const [params] = useSearchParams()
  const [tab, setTab] = useState<'open' | 'submitted' | 'all'>('open')
  const [classFilter, setClassFilter] = useState('all')
  const [createOpen, setCreateOpen] = useState(params.get('create') === '1')

  if (!currentUser) return null
  const classes = visibleClasses(db, currentUser)
  const classIds = new Set(classes.map((c) => c.id))
  const isStudent = currentUser.role === 'student'
  const canManage = currentUser.role === 'teacher' || currentUser.role === 'admin'

  const published = db.quizzes.filter((q) => classIds.has(q.classId) && (canManage || q.published))
  const attemptedIds = new Set(db.attempts.filter((a) => a.studentId === currentUser.id).map((a) => a.quizId))
  const open = isStudent ? openQuizzesFor(db, currentUser.id).filter((q) => classFilter === 'all' || q.classId === classFilter) : published.filter((q) => q.published)

  const list = useMemo(() => {
    const base = published.filter((q) => classFilter === 'all' || q.classId === classFilter)
    if (!isStudent) return base.sort((a, b) => Number(a.published) - Number(b.published) || b.createdAt.localeCompare(a.createdAt))
    if (tab === 'open') return open
    if (tab === 'submitted') return base.filter((q) => attemptedIds.has(q.id))
    return base
  }, [published, classFilter, isStudent, tab, open, attemptedIds])

  const togglePublish = (quiz: Quiz) => {
    mutate((draft) => {
      const q = draft.quizzes.find((x) => x.id === quiz.id)
      if (q) q.published = !q.published
    })
    toast('success', quiz.published ? t('common.draft') : t('quiz.published'))
  }

  const remove = (quiz: Quiz) => {
    if (!window.confirm(t('quiz.deleteConfirm'))) return
    mutate((draft) => {
      draft.quizzes = draft.quizzes.filter((q) => q.id !== quiz.id)
      draft.attempts = draft.attempts.filter((a) => a.quizId !== quiz.id)
    })
    toast('success', t('quiz.deleted'))
  }

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('quiz.title')}
        subtitle={canManage ? t('quiz.teacherSub') : t('quiz.sub')}
        icon="clipboard"
        actions={canManage ? <Button icon="plus" onClick={() => setCreateOpen(true)}>{t('quiz.create')}</Button> : null}
      />

      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        {isStudent ? (
          <Tabs
            items={[
              { id: 'open', label: t('quiz.pending'), count: open.length },
              { id: 'submitted', label: t('quiz.submitted'), count: published.filter((q) => attemptedIds.has(q.id)).length },
              { id: 'all', label: t('quiz.all'), count: published.length },
            ]}
            value={tab}
            onChange={(id) => setTab(id as typeof tab)}
            className="flex-1"
          />
        ) : (
          <Tabs
            items={[
              { id: 'open', label: t('common.published'), count: published.filter((q) => q.published).length },
              { id: 'submitted', label: t('common.draft'), count: published.filter((q) => !q.published).length },
              { id: 'all', label: t('common.all'), count: published.length },
            ]}
            value={tab}
            onChange={(id) => setTab(id as typeof tab)}
            className="flex-1"
          />
        )}
        {classes.length > 1 ? (
          <Select value={classFilter} onChange={(e) => setClassFilter(e.target.value)} className="sm:w-60" aria-label={t('common.class')}>
            <option value="all">{t('common.all')} {t('common.class').toLowerCase()}es</option>
            {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </Select>
        ) : null}
      </div>

      {canManage ? (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          {[
            { label: t('common.published'), value: published.filter((q) => q.published).length, icon: 'checkCircle' as const },
            { label: t('common.draft'), value: published.filter((q) => !q.published).length, icon: 'edit' as const },
            { label: t('quiz.submitted'), value: db.attempts.filter((a) => published.some((q) => q.id === a.quizId)).length, icon: 'clipboard' as const },
            { label: t('quiz.viewAttempts'), value: published.reduce((s, q) => s + attemptsForQuiz(db, q.id).length, 0), icon: 'chart' as const },
          ].map((s) => (
            <div key={s.label} className="card flex items-center gap-2.5 p-3">
              <span className="grid h-9 w-9 place-items-center rounded-lg bg-brand-50 text-brand-700"><Icon name={s.icon} size={16} /></span>
              <div><p className="text-[10px] text-ink-500">{s.label}</p><p className="text-lg font-bold tabular-nums text-ink-900">{s.value}</p></div>
            </div>
          ))}
        </div>
      ) : null}

      {isStudent && !open.length && tab === 'open' ? (
        <Callout tone="success" icon="checkCircle" title={t('quiz.noPending')}>{t('dash.allCaughtUp')}</Callout>
      ) : null}

      {list.length ? (
        <div className="grid gap-3 lg:grid-cols-2">
          {list.map((quiz) => {
            const attempts = attemptsForQuiz(db, quiz.id, isStudent ? currentUser.id : undefined)
            const used = attempts.length
            const visible = quizResultsVisible(quiz)
            const latest = attempts[0]
            return (
              <QuizRow
                key={quiz.id}
                quiz={quiz}
                status={!quiz.published ? t('common.draft') : quizResultsVisible(quiz) ? t('common.results') : undefined}
                action={
                  <div className="flex flex-col items-stretch gap-1.5">
                    {isStudent ? (
                      <>
                        {quiz.published && used < quiz.attemptsAllowed ? (
                          <Link to={`/quizzes/${quiz.id}`} className={buttonClass('primary', 'sm')}>{used ? t('quiz.start') : t('quiz.start')}</Link>
                        ) : null}
                        {latest ? (
                          visible ? (
                            <Link to={`/quizzes/${quiz.id}`} className={buttonClass('secondary', 'sm')}>
                              {t('common.results')} · {latest.score}/{latest.maxScore}
                            </Link>
                          ) : (
                            <span className="inline-flex items-center gap-1 rounded-lg border border-ink-200 px-2 py-1.5 text-[10px] text-ink-500"><Icon name="lock" size={12} /> {t('marks.notPublished')}</span>
                          )
                        ) : null}
                        <span className="text-center text-[10px] text-ink-400">{used}/{quiz.attemptsAllowed} {t('quiz.attemptsUsed').toLowerCase()}</span>
                      </>
                    ) : (
                      <>
                        <Link to={`/quizzes/${quiz.id}`} className={buttonClass('secondary', 'sm')}>{t('quiz.viewAttempts')} ({attemptsForQuiz(db, quiz.id).length})</Link>
                        <Button size="sm" variant="ghost" onClick={() => togglePublish(quiz)}>{quiz.published ? t('common.unpublish') : t('common.publish')}</Button>
                        <Button size="sm" variant="ghost" onClick={() => remove(quiz)} aria-label={t('common.delete')}><Icon name="trash" size={14} /></Button>
                      </>
                    )}
                  </div>
                }
              />
            )
          })}
        </div>
      ) : (
        <EmptyState
          icon="clipboard"
          title={isStudent ? (tab === 'submitted' ? t('quiz.noAttemptsYet') : t('quiz.noPending')) : t('common.noData')}
          description={canManage ? t('quiz.teacherSub') : t('quiz.sub')}
          action={canManage ? <Button icon="plus" onClick={() => setCreateOpen(true)}>{t('quiz.create')}</Button> : null}
        />
      )}

      {canManage ? <CreateQuizModal open={createOpen} onClose={() => setCreateOpen(false)} classes={classes} /> : null}
    </div>
  )
}

const emptyQuestion = (type: Question['type']): Question => ({
  id: uid('q'),
  type,
  prompt: '',
  options: type === 'mcq' ? ['', '', '', ''] : undefined,
  answer: '',
  accept: [],
  explanation: '',
  points: 1,
})

function CreateQuizModal({ open, onClose, classes }: { open: boolean; onClose: () => void; classes: ReturnType<typeof visibleClasses> }) {
  const { db, currentUser, mutate, toast } = useApp()
  const { t } = useI18n()
  const [title, setTitle] = useState('')
  const [classId, setClassId] = useState(classes[0]?.id || '')
  const [subjectId, setSubjectId] = useState(classes[0]?.subjectIds[0] || 'math')
  const [instructions, setInstructions] = useState('')
  const [openAt, setOpenAt] = useState(todayISO())
  const [dueAt, setDueAt] = useState('')
  const [attemptsAllowed, setAttemptsAllowed] = useState(1)
  const [timeLimitMin, setTimeLimitMin] = useState(15)
  const [showResults, setShowResults] = useState<Quiz['showResults']>('immediately')
  const [showAnswers, setShowAnswers] = useState(true)
  const [published, setPublished] = useState(false)
  const [questions, setQuestions] = useState<Question[]>([emptyQuestion('mcq')])
  const [errors, setErrors] = useState<Record<string, string>>({})

  const updateQuestion = (index: number, patch: Partial<Question>) => {
    setQuestions((prev) => prev.map((q, i) => (i === index ? { ...q, ...patch } : q)))
  }

  const submit = () => {
    if (!currentUser) return
    const next: Record<string, string> = {}
    if (title.trim().length < 3 || !classId || !subjectId) next.required = t('quiz.required')
    if (openAt && dueAt && dueAt < openAt) next.dates = t('quiz.dueBeforeOpen')
    for (const q of questions) {
      if (!q.prompt.trim() || !q.answer.trim()) next.questions = t('common.required')
      if (q.type === 'mcq' && (q.options || []).filter((o) => o.trim()).length < 2) next.questions = t('common.required')
    }
    if (Object.keys(next).length) {
      setErrors(next)
      return
    }
    mutate((draft) => {
      draft.quizzes.unshift({
        id: uid('quiz'),
        classId,
        subjectId,
        title: title.trim(),
        instructions: instructions.trim() || t('quiz.instructions'),
        published,
        openAt: openAt || undefined,
        dueAt: dueAt || undefined,
        showResults,
        showAnswers,
        resultsReleased: showResults === 'immediately' ? true : false,
        attemptsAllowed,
        timeLimitMin,
        questions: questions.map((q) => ({
          ...q,
          prompt: q.prompt.trim(),
          answer: q.answer.trim(),
          options: q.type === 'mcq' ? (q.options || []).map((o) => o.trim()).filter(Boolean) : undefined,
        })),
        createdBy: currentUser.id,
        createdAt: new Date().toISOString(),
        language: currentUser.language,
      })
      for (const student of draft.users.filter((u) => u.role === 'student' && draft.enrollments.some((e) => e.classId === classId && e.studentId === u.id && e.status === 'active'))) {
        if (!published) break
        draft.notifications.unshift({
          id: uid('notif'),
          userId: student.id,
          kind: 'quiz',
          title: `${t('quiz.title')}: ${title.trim()}`,
          body: `${db.classes.find((c) => c.id === classId)?.name || ''} · ${attemptsAllowed} ${t('quiz.attemptsAllowed').toLowerCase()}`,
          link: '/quizzes',
          read: false,
          createdAt: new Date().toISOString(),
        })
      }
    })
    toast('success', published ? t('quiz.published') : t('common.draft'), title.trim())
    setTitle('')
    setInstructions('')
    setQuestions([emptyQuestion('mcq')])
    setErrors({})
    onClose()
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={t('quiz.create')}
      description={t('quiz.teacherSub')}
      size="xl"
      footer={<><Button variant="secondary" onClick={onClose}>{t('common.cancel')}</Button><Button onClick={submit} icon="check">{published ? t('common.publish') : t('common.save')}</Button></>}
    >
      <div className="space-y-4">
        {errors.required ? <Callout tone="danger" title={errors.required} /> : null}
        {errors.questions ? <Callout tone="danger" title={errors.questions} /> : null}
        {errors.dates ? <Callout tone="danger" title={errors.dates} /> : null}
        <Field label={t('live.name')} htmlFor="quiz-title" required>
          <TextInput id="quiz-title" value={title} onChange={(e) => setTitle(e.target.value)} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('common.class')} htmlFor="quiz-class" required>
            <Select id="quiz-class" value={classId} onChange={(e) => { setClassId(e.target.value); setSubjectId(classes.find((c) => c.id === e.target.value)?.subjectIds[0] || 'math') }}>
              {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </Field>
          <Field label={t('common.subject')} htmlFor="quiz-subject" required>
            <Select id="quiz-subject" value={subjectId} onChange={(e) => setSubjectId(e.target.value)}>
              {(classes.find((c) => c.id === classId)?.subjectIds || []).map((s) => <option key={s} value={s}>{subjectLabel(s, t)}</option>)}
            </Select>
          </Field>
        </div>
        <Field label={t('common.instructions')} htmlFor="quiz-instructions">
          <TextArea id="quiz-instructions" value={instructions} onChange={(e) => setInstructions(e.target.value)} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-4">
          <Field label={t('quiz.openAt') || 'Opens'} htmlFor="quiz-open">
            <TextInput id="quiz-open" type="date" value={openAt} onChange={(e) => setOpenAt(e.target.value)} />
          </Field>
          <Field label={t('common.due')} htmlFor="quiz-due">
            <TextInput id="quiz-due" type="date" value={dueAt} min={openAt} onChange={(e) => setDueAt(e.target.value)} />
          </Field>
          <Field label={t('quiz.attemptsAllowed')} htmlFor="quiz-attempts">
            <TextInput id="quiz-attempts" type="number" min={1} max={5} value={attemptsAllowed} onChange={(e) => setAttemptsAllowed(Number(e.target.value))} />
          </Field>
          <Field label={t('quiz.timeLimit', { min: '' }).replace('  ', ' ')} htmlFor="quiz-time">
            <TextInput id="quiz-time" type="number" min={1} value={timeLimitMin} onChange={(e) => setTimeLimitMin(Number(e.target.value))} />
          </Field>
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('quiz.showResults')} htmlFor="quiz-visibility">
            <Select id="quiz-visibility" value={showResults} onChange={(e) => setShowResults(e.target.value as Quiz['showResults'])}>
              <option value="immediately">{t('quiz.immediate')}</option>
              <option value="after_due">{t('quiz.afterDueShort')}</option>
              <option value="manual">{t('quiz.manualShort')}</option>
            </Select>
          </Field>
          <div className="space-y-2 pt-5">
            <Toggle checked={showAnswers} onChange={setShowAnswers} label={t('quiz.showAnswers')} />
            <Toggle checked={published} onChange={setPublished} label={t('common.publish')} description={t('quiz.publishHint')} />
          </div>
        </div>

        <div className="rounded-xl border border-ink-200 p-3">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="text-sm font-bold text-ink-900">{t('quiz.builder')} <span className="text-xs font-normal text-ink-500">({questions.length})</span></p>
            <div className="flex gap-1.5">
              <Button size="sm" variant="secondary" icon="plus" onClick={() => setQuestions((q) => [...q, emptyQuestion('mcq')])}>{t('quiz.addMcq')}</Button>
              <Button size="sm" variant="secondary" icon="plus" onClick={() => setQuestions((q) => [...q, emptyQuestion('fill')])}>{t('quiz.addFill')}</Button>
            </div>
          </div>
          <div className="mt-3 space-y-3">
            {questions.map((q, index) => (
              <div key={q.id} className="rounded-xl border border-ink-200 bg-ink-50/50 p-3">
                <div className="flex items-center justify-between gap-2">
                  <Badge tone={q.type === 'mcq' ? 'brand' : 'leaf'}>{q.type === 'mcq' ? t('quiz.addMcq') : t('quiz.addFill')} · {index + 1}</Badge>
                  <button type="button" onClick={() => setQuestions((prev) => prev.filter((_, i) => i !== index))} disabled={questions.length === 1} className="rounded p-1 text-ink-400 hover:bg-clay-50 hover:text-clay-700 disabled:opacity-40" aria-label={t('common.delete')}>
                    <Icon name="trash" size={14} />
                  </button>
                </div>
                <div className="mt-2 space-y-2">
                  <TextInput value={q.prompt} onChange={(e) => updateQuestion(index, { prompt: e.target.value })} placeholder={t('quiz.question')} aria-label={t('quiz.question')} />
                  {q.type === 'mcq' ? (
                    <div className="grid gap-1.5 sm:grid-cols-2">
                      {(q.options || []).map((opt, oi) => (
                        <TextInput
                          key={oi}
                          value={opt}
                          onChange={(e) => updateQuestion(index, { options: (q.options || []).map((x, xi) => (xi === oi ? e.target.value : x)) })}
                          placeholder={t('quiz.option', { n: oi + 1 })}
                          aria-label={t('quiz.option', { n: oi + 1 })}
                        />
                      ))}
                    </div>
                  ) : null}
                  <div className="grid gap-2 sm:grid-cols-2">
                    <TextInput value={q.answer} onChange={(e) => updateQuestion(index, { answer: e.target.value })} placeholder={t('quiz.answer')} aria-label={t('quiz.answer')} />
                    <TextInput value={q.explanation} onChange={(e) => updateQuestion(index, { explanation: e.target.value })} placeholder={t('quiz.explanation')} aria-label={t('quiz.explanation')} />
                  </div>
                  <div className="flex items-center gap-2">
                    <label className="text-[11px] text-ink-500">{t('common.points')}</label>
                    <TextInput type="number" min={1} max={10} value={q.points} onChange={(e) => updateQuestion(index, { points: Number(e.target.value) })} className="w-20" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
        <Callout tone="info" title={t('quiz.requiresInternet')}>{t('quiz.sampleContent')}</Callout>
      </div>
    </Modal>
  )
}

