                                <p className="mt-1 text-xs text-ink-700">
                                  <span className="font-semibold">{t('quiz.yourAnswer')}:</span> {given || '—'}{' '}
                                  <Badge tone={ok ? 'leaf' : 'clay'} icon={ok ? 'check' : 'x'}>{ok ? t('quiz.correct') : t('quiz.incorrect')}</Badge>
                                </p>
