import {
  attendanceSummary,
  classById,
  guardianChildren,
  marksForStudent,
  schoolById,
  studentClassIds,
  visibleClasses,
} from '../lib/access'
import { downloadTextFile, formatDate, hashPassword, makeSalt, uid } from '../lib/utils'
import type { Lang } from '../lib/types'
import { Icon } from '../components/Icon'
import { AllBadges } from '../components/shared'
import {
  Badge,
