import { useState } from 'react'
import { Link } from 'react-router-dom'
import { useApp } from '../lib/store'
import { useI18n } from '../lib/i18n'
import { classById, guardianChildren, schoolById, studentClassIds } from '../lib/access'
import { formatDateTime, normaliseCode, uid } from '../lib/utils'
import { Icon } from '../components/Icon'
import {
  Badge,
  Button,
  Callout,
  Card,
  Field,
  InfoList,
  PageHeader,
  SectionCard,
  TextArea,
  TextInput,
} from '../components/ui'

export function ParentLinkPage() {
  const { db, currentUser, mutate, toast } = useApp()
  const { t, lang } = useI18n()
  const [mode, setMode] = useState<'code' | 'approval'>('code')
  const [code, setCode] = useState('')
  const [childName, setChildName] = useState('')
  const [note, setNote] = useState('')
  const [error, setError] = useState('')

  if (!currentUser) return null
  if (currentUser.role !== 'parent') {
    return (
      <div className="mx-auto max-w-xl py-10">
        <Callout tone="warn" title={t('state.forbiddenTitle')}>{t('parent.accessNote')} {t('state.forbiddenBody')}</Callout>
        <Link to="/dashboard" className="mt-3 inline-flex items-center gap-1 text-sm font-semibold text-brand-700 hover:underline">
          {t('state.goHome')} <Icon name="arrowRight" size={15} />
        </Link>
      </div>
    )
  }

  const school = schoolById(db, currentUser.schoolId)
  const children = guardianChildren(db, currentUser.id)
  const links = db.parentLinks.filter((l) => l.parentId === currentUser.id).sort((a, b) => b.requestedAt.localeCompare(a.requestedAt))

  const linkByCode = () => {
    setError('')
    const student = db.users.find(
      (u) => u.role === 'student' && u.schoolId === currentUser.schoolId && normaliseCode(u.inviteCode || '') === normaliseCode(code),
    )
    if (!student) {
      setError(t('prof.linkInvalid'))
      return
    }
    const existing = db.parentLinks.find((l) => l.parentId === currentUser.id && l.studentId === student.id)
    if (existing?.status === 'approved') {
      setError(t('prof.linkExists'))
      return
    }
    mutate((draft) => {
      if (existing) {
        const target = draft.parentLinks.find((l) => l.id === existing.id)
        if (target) {
          target.status = 'approved'
          target.respondedAt = new Date().toISOString()
          target.method = 'code'
          target.note = 'Invitation code verified.'
        }
      } else {
        draft.parentLinks.push({
          id: uid('pl'),
          parentId: currentUser.id,
          studentId: student.id,
          status: 'approved',
          requestedAt: new Date().toISOString(),
          respondedAt: new Date().toISOString(),
          method: 'code',
          note: 'Invitation code verified.',
        })
      }
      const cls = studentClassIds(db, student.id).map((id) => classById(db, id))[0]
      for (const userId of [student.id, cls?.teacherId].filter(Boolean) as string[]) {
        draft.notifications.unshift({
          id: uid('notif'),
          userId,
          kind: 'link',
          title: `${currentUser.name} linked as a guardian`,
          body: `${currentUser.name} used the invitation code for ${student.name}.`,
          link: userId === student.id ? '/profile' : '/admin/approvals',
          read: false,
          createdAt: new Date().toISOString(),
        })
      }
      draft.audit.unshift({
        id: uid('aud'),
        actorId: currentUser.id,
        actorName: currentUser.name,
        actorRole: 'parent',
        action: 'Linked guardian account',
        detail: `Verified invitation code for ${student.name}.`,
        at: new Date().toISOString(),
      })
    })
    toast('success', t('prof.approved'))
    setCode('')
  }

  const requestLink = () => {
    setError('')
    if (childName.trim().length < 3) {
      setError(t('prof.linkInvalid'))
      return
    }
    const matches = db.users.filter(
      (u) => u.role === 'student' && u.schoolId === currentUser.schoolId && u.name.toLowerCase() === childName.trim().toLowerCase(),
    )
    if (matches.length !== 1) {
      setError(t('prof.linkInvalid'))
      return
    }
    const student = matches[0]
    const existing = db.parentLinks.find((l) => l.parentId === currentUser.id && l.studentId === student.id)
    if (existing) {
      setError(t('prof.linkExists'))
      return
    }
    mutate((draft) => {
      draft.parentLinks.push({
        id: uid('pl'),
        parentId: currentUser.id,
        studentId: student.id,
        status: 'pending',
        requestedAt: new Date().toISOString(),
        method: 'approval',
        note: note.trim() || undefined,
      })
      draft.notifications.unshift({
        id: uid('notif'),
        userId: student.id,
        kind: 'link',
        title: 'Guardian link request',
        body: `${currentUser.name} asked to link to your account. Approve only if this is your guardian.`,
        link: '/profile',
        read: false,
        createdAt: new Date().toISOString(),
      })
      for (const admin of draft.users.filter((u) => u.role === 'admin' && u.schoolId === currentUser.schoolId)) {
        draft.notifications.unshift({
          id: uid('notif'),
          userId: admin.id,
          kind: 'link',
          title: 'Guardian link request awaiting approval',
          body: `${currentUser.name} requested a link to ${student.name}.`,
          link: '/admin/approvals',
          read: false,
          createdAt: new Date().toISOString(),
        })
      }
    })
    toast('success', t('prof.linkRequested'))
    setChildName('')
    setNote('')
  }

  const cancelRequest = (id: string) => {
    mutate((draft) => {
      const link = draft.parentLinks.find((l) => l.id === id)
      if (link) {
        link.status = 'rejected'
        link.respondedAt = new Date().toISOString()
      }
    })
    toast('success', t('prof.rejected'))
  }

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader title={t('parent.linkTitle')} subtitle={t('parent.linkSub')} icon="link" />

      <Callout tone="info" icon="shield" title={t('parent.accessNote')}>
        {t('parent.noChildHint')} {t('parent.inviteHint')}
      </Callout>

      <div className="grid gap-4 lg:grid-cols-[1.1fr_1fr]">
        <SectionCard title={t('parent.linkTitle')} subtitle={t('parent.linkMethod')} icon="link">
          <div className="mb-3 grid grid-cols-2 gap-2">
            <button
              type="button"
              onClick={() => setMode('code')}
              aria-pressed={mode === 'code'}
              className={`min-h-11 rounded-xl border px-3 text-xs font-semibold ${mode === 'code' ? 'border-brand-600 bg-brand-50 text-brand-800' : 'border-ink-200 text-ink-600 hover:bg-ink-50'}`}
            >
              {t('parent.linkCode')}
            </button>
            <button
              type="button"
              onClick={() => setMode('approval')}
              aria-pressed={mode === 'approval'}
              className={`min-h-11 rounded-xl border px-3 text-xs font-semibold ${mode === 'approval' ? 'border-brand-600 bg-brand-50 text-brand-800' : 'border-ink-200 text-ink-600 hover:bg-ink-50'}`}
            >
              {t('parent.linkApproval')}
            </button>
          </div>

          {error ? <Callout tone="danger" title={error} /> : null}

          {mode === 'code' ? (
            <div className="space-y-3">
              <Field label={t('parent.inviteCode')} htmlFor="parent-code" hint={t('parent.inviteHint')} required>
                <TextInput id="parent-code" value={code} onChange={(e) => setCode(e.target.value.toUpperCase())} placeholder="AARAV-4821" className="font-mono tracking-wider" />
              </Field>
              <Button icon="link" onClick={linkByCode} disabled={code.trim().length < 4}>{t('prof.requestLink')}</Button>
              <p className="text-[10px] leading-relaxed text-ink-400">{t('parent.accessNote')}</p>
            </div>
          ) : (
            <div className="space-y-3">
              <Field label={t('common.fullName')} htmlFor="parent-child" hint="Enter the student’s full name exactly as it appears on their account." required>
                <TextInput id="parent-child" value={childName} onChange={(e) => setChildName(e.target.value)} placeholder="Imran Khan" />
              </Field>
              <Field label={t('common.note')} htmlFor="parent-note" hint={t('common.optional')}>
                <TextArea id="parent-note" value={note} onChange={(e) => setNote(e.target.value)} placeholder="I am Imran’s mother. Please verify with the class teacher." />
              </Field>
              <Button icon="message" onClick={requestLink} disabled={childName.trim().length < 3}>{t('prof.requestLink')}</Button>
              <p className="text-[10px] leading-relaxed text-ink-400">{t('prof.linkHint')}</p>
            </div>
          )}
        </SectionCard>

        <div className="space-y-4">
          <SectionCard title={t('prof.linkedChildren')} subtitle={`${children.length} ${t('common.approved').toLowerCase()}`} icon="users">
            {children.length ? (
              <ul className="space-y-2">
                {children.map((child) => {
                  const cls = studentClassIds(db, child.id).map((id) => classById(db, id))[0]
                  return (
                    <li key={child.id} className="rounded-xl border border-ink-200 p-3">
                      <p className="text-sm font-bold text-ink-900">{child.name}</p>
                      <p className="mt-0.5 text-[11px] text-ink-500">{cls?.name} · {t('role.student')} · {child.rollNo ? `${t('classes.rollNo')} ${child.rollNo}` : ''}</p>
                      <Link to="/attendance" className="mt-1.5 inline-flex items-center gap-1 text-[11px] font-semibold text-brand-700 hover:underline">
                        {t('parent.childDetail')} <Icon name="arrowRight" size={12} />
                      </Link>
                    </li>
                  )
                })}
              </ul>
            ) : (
              <p className="text-xs text-ink-500">{t('parent.noChildHint')}</p>
            )}
          </SectionCard>

          <SectionCard title={t('prof.pendingLinks')} icon="clock">
            {links.length ? (
              <ul className="divide-y divide-ink-100">
                {links.map((link) => {
                  const student = db.users.find((u) => u.id === link.studentId)
                  return (
                    <li key={link.id} className="flex flex-wrap items-center justify-between gap-2 py-2 text-xs">
                      <div>
                        <p className="font-semibold text-ink-800">{student?.name}</p>
                        <p className="text-[10px] text-ink-400">{formatDateTime(link.requestedAt, lang)} · {link.method === 'code' ? t('parent.linkCode') : t('parent.linkApproval')}</p>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Badge tone={link.status === 'approved' ? 'leaf' : link.status === 'pending' ? 'saffron' : 'clay'}>
                          {t(`common.${link.status}`)}
                        </Badge>
                        {link.status === 'pending' ? (
                          <Button size="sm" variant="ghost" onClick={() => cancelRequest(link.id)}>{t('common.cancel')}</Button>
                        ) : null}
                      </div>
                    </li>
                  )
                })}
              </ul>
            ) : (
              <p className="text-xs text-ink-500">{t('parent.noChild')}</p>
            )}
          </SectionCard>

          <Card className="p-4">
            <p className="flex items-center gap-1.5 text-sm font-bold text-ink-900"><Icon name="school" size={16} className="text-brand-600" /> {school?.name}</p>
            <InfoList
              items={[
                { label: t('common.school'), value: school?.code || '—' },
                { label: t('common.relationship'), value: currentUser.relationship || '—' },
                { label: t('common.phone'), value: currentUser.phone || '—' },
              ]}
            />
            <p className="mt-2 text-[10px] leading-relaxed text-ink-400">{t('privacy.demoNote')}</p>
          </Card>
        </div>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useApp } from '../../lib/store'
import { useI18n } from '../../lib/i18n'
import { classById, classStudents, pendingParentLinksForAdmin, schoolById, visibleClasses } from '../../lib/access'
import { RESOURCE_TYPE_LABEL } from '../../lib/subjects'
import { downloadTextFile, formatDate, hashPassword, makeSalt, readConfig, subjectLabel, uid } from '../../lib/utils'
import { toCsv } from '../../lib/offline'
import type { Role, School, User } from '../../lib/types'
import { Icon } from '../../components/Icon'
import { Avatar, Badge, Button, Callout, Card, CopyButton, EmptyState, Field, InfoList, Modal, PageHeader, SectionCard, Select, StatCard, Switch, TextInput, Toggle, buttonClass } from '../../components/ui'
export { AdminFeedbackPage } from '../Feedback'
export { ScholarshipsPage as AdminScholarshipsPage } from '../Scholarships'

const ROLES: Role[] = ['student', 'teacher', 'parent', 'admin']

const requireAdmin = (role?: string) => role === 'admin'

export function AdminSchoolsPage() {
  const { db, currentUser, mutate, toast } = useApp()
  const { t } = useI18n()
  const [editing, setEditing] = useState<School | null>(null)
  const [open, setOpen] = useState(false)

  if (!currentUser || !requireAdmin(currentUser.role)) return null
  const schools = db.schools

  const remove = (school: School) => {
    const inUse = db.users.some((u) => u.schoolId === school.id) || db.classes.some((c) => c.schoolId === school.id)
    if (inUse) {
      toast('error', t('admin.schoolInUse'))
      return
    }
    if (!window.confirm(`${t('admin.deleteSchool')} — ${school.name}?`)) return
    mutate((draft) => {
      draft.schools = draft.schools.filter((s) => s.id !== school.id)
    })
    toast('success', t('admin.schoolSaved'))
  }

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('admin.schools')}
        subtitle={t('admin.sub')}
        icon="school"
        actions={<Button icon="plus" onClick={() => { setEditing(null); setOpen(true) }}>{t('admin.addSchool')}</Button>}
      />

      <div className="grid gap-3 sm:grid-cols-3">
        <StatCard label={t('admin.schools')} value={schools.length} icon="school" />
        <StatCard label={t('admin.students')} value={db.users.filter((u) => u.role === 'student').length} icon="graduation" tone="leaf" />
        <StatCard label={t('admin.teachers')} value={db.users.filter((u) => u.role === 'teacher').length} icon="users" tone="brand" />
      </div>

      <div className="grid gap-3 lg:grid-cols-2">
        {schools.map((school) => {
          const users = db.users.filter((u) => u.schoolId === school.id)
          const classes = db.classes.filter((c) => c.schoolId === school.id)
          return (
            <Card key={school.id} className="p-4">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div>
                  <h2 className="text-sm font-bold text-ink-900">{school.name}</h2>
                  <p className="mt-0.5 text-[11px] text-ink-500">{school.code} · {school.district}, {school.state}</p>
                </div>
                <Badge tone="brand" icon="users">{users.length} {t('admin.users').toLowerCase()}</Badge>
              </div>
              <InfoList
                items={[
                  { label: t('admin.threshold'), value: `${school.lowAttendanceThreshold}%` },
                  { label: t('admin.classes'), value: `${classes.length}` },
                  { label: t('admin.contactEmail'), value: school.contactEmail },
                  { label: t('admin.contactPhone'), value: school.contactPhone },
                ]}
              />
              <div className="mt-2 flex flex-wrap gap-1.5">
                <Button size="sm" variant="secondary" icon="edit" onClick={() => { setEditing(school); setOpen(true) }}>{t('common.edit')}</Button>
                <Button size="sm" variant="ghost" icon="trash" onClick={() => remove(school)}>{t('admin.deleteSchool')}</Button>
              </div>
            </Card>
          )
        })}
      </div>

      <SchoolForm open={open} onClose={() => setOpen(false)} school={editing} />
    </div>
  )
}

function SchoolForm({ open, onClose, school }: { open: boolean; onClose: () => void; school: School | null }) {
  const { currentUser, mutate, toast } = useApp()
  const { t } = useI18n()
  const [name, setName] = useState(school?.name || '')
  const [code, setCode] = useState(school?.code || '')
  const [district, setDistrict] = useState(school?.district || '')
  const [state, setState] = useState(school?.state || 'Uttar Pradesh')
  const [threshold, setThreshold] = useState(school?.lowAttendanceThreshold || 75)
  const [contactEmail, setContactEmail] = useState(school?.contactEmail || '')
  const [contactPhone, setContactPhone] = useState(school?.contactPhone || '')
  const [error, setError] = useState('')

  const submit = () => {
    if (!currentUser) return
    if (name.trim().length < 3 || code.trim().length < 2 || district.trim().length < 2) {
      setError(t('admin.required'))
      return
    }
    const saved: School = {
      id: school?.id || uid('sch'),
      name: name.trim(),
      code: code.trim().toUpperCase(),
      district: district.trim(),
      state: state.trim(),
      lowAttendanceThreshold: Math.min(100, Math.max(1, threshold)),
      contactEmail: contactEmail.trim(),
      contactPhone: contactPhone.trim(),
      createdAt: school?.createdAt || new Date().toISOString(),
    }
    mutate((draft) => {
      const idx = draft.schools.findIndex((s) => s.id === saved.id)
      if (idx >= 0) draft.schools[idx] = saved
      else draft.schools.push(saved)
      draft.audit.unshift({
        id: uid('aud'),
        actorId: currentUser.id,
        actorName: currentUser.name,
        actorRole: currentUser.role,
        action: school ? 'Updated school' : 'Added school',
        detail: saved.name,
        at: new Date().toISOString(),
      })
    })
    toast('success', t('admin.schoolSaved'))
    setError('')
    onClose()
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={school ? t('admin.schools') : t('admin.addSchool')}
      footer={<><Button variant="secondary" onClick={onClose}>{t('common.cancel')}</Button><Button icon="check" onClick={submit}>{t('common.save')}</Button></>}
    >
      <div className="space-y-3.5">
        {error ? <Callout tone="danger" title={error} /> : null}
        <Field label={t('admin.schoolName')} htmlFor="school-name" required>
          <TextInput id="school-name" value={name} onChange={(e) => setName(e.target.value)} />
        </Field>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('admin.schoolCode')} htmlFor="school-code" required>
            <TextInput id="school-code" value={code} onChange={(e) => setCode(e.target.value)} />
          </Field>
          <Field label={t('admin.district')} htmlFor="school-district" required>
            <TextInput id="school-district" value={district} onChange={(e) => setDistrict(e.target.value)} />
          </Field>
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('admin.state')} htmlFor="school-state">
            <TextInput id="school-state" value={state} onChange={(e) => setState(e.target.value)} />
          </Field>
          <Field label={t('admin.threshold')} htmlFor="school-threshold">
            <TextInput id="school-threshold" type="number" min={1} max={100} value={threshold} onChange={(e) => setThreshold(Number(e.target.value))} />
          </Field>
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label={t('admin.contactEmail')} htmlFor="school-email">
            <TextInput id="school-email" type="email" value={contactEmail} onChange={(e) => setContactEmail(e.target.value)} />
          </Field>
          <Field label={t('admin.contactPhone')} htmlFor="school-phone">
            <TextInput id="school-phone" value={contactPhone} onChange={(e) => setContactPhone(e.target.value)} />
          </Field>
        </div>
      </div>
    </Modal>
  )
}

export function AdminUsersPage() {
  const { db, currentUser, mutate, toast } = useApp()
  const { t } = useI18n()
  const [role, setRole] = useState('all')
  const [query, setQuery] = useState('')
  const [addOpen, setAddOpen] = useState(false)

  if (!currentUser || !requireAdmin(currentUser.role)) return null

  const base = db.users.filter((u) => u.schoolId === currentUser.schoolId || currentUser.role === 'admin')
  const list = base
    .filter((u) => role === 'all' || u.role === role)
    .filter((u) => !query.trim() || `${u.name} ${u.email}`.toLowerCase().includes(query.trim().toLowerCase()))
    .sort((a, b) => a.role.localeCompare(b.role) || a.name.localeCompare(b.name))

  const toggleDisabled = (user: User) => {
    if (user.id === currentUser.id) {
      toast('error', t('common.errorTitle'), 'You cannot disable your own account.')
      return
    }
    mutate((draft) => {
      const target = draft.users.find((u) => u.id === user.id)
      if (target) target.disabled = !target.disabled
      draft.audit.unshift({
        id: uid('aud'),
        actorId: currentUser.id,
        actorName: currentUser.name,
        actorRole: currentUser.role,
        action: user.disabled ? 'Enabled account' : 'Disabled account',
        detail: `${user.name} (${user.role})`,
        at: new Date().toISOString(),
      })
    })
    toast('success', user.disabled ? t('admin.enabledToast') : t('admin.disabledToast'))
  }

  const exportUsers = () => {
    const rows = [
      ['Name', 'Email', 'Role', 'Phone', 'Class', 'Disabled', 'Created'],
      ...list.map((u) => [
        u.name,
        u.email,
        u.role,
        u.phone || '',
        u.role === 'student' ? `${u.gradeLevel || ''}${u.section || ''}` : '',
        u.disabled ? 'yes' : 'no',
        u.createdAt,
      ]),
    ]
    downloadTextFile('vidyagram-users.csv', toCsv(rows))
    toast('success', t('common.export'))
  }

  return (
    <div className="space-y-4 sm:space-y-5">
      <PageHeader
        title={t('admin.users')}
        subtitle={t('admin.sub')}
        icon="users"
        actions={
          <>
            <Button variant="secondary" icon="download" onClick={exportUsers}>{t('admin.exportUsers')}</Button>
            <Button icon="plus" onClick={() => setAddOpen(true)}>{t('admin.addUser')}</Button>
          </>
        }
      />

      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        {ROLES.map((r) => (
          <button
            key={r}
            type="button"
            onClick={() => setRole(role === r ? 'all' : r)}
            className={`card p-3 text-left ${role === r ? 'ring-2 ring-brand-400' : ''}`}
            aria-pressed={role === r}
          >
            <p className="text-[10px] text-ink-500">{t(`role.${r}`)}</p>
            <p className="text-xl font-bold text-ink-900">{base.filter((u) => u.role === r).length}</p>
          </button>
        ))}
      </div>

      <SectionCard icon="filter" bodyClassName="space-y-3">
        <div className="relative">
          <Icon name="search" size={16} className="pointer-events-none absolute left-3 top-3 text-ink-400" />
          <TextInput value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t('admin.searchUsers')} aria-label={t('admin.searchUsers')} className="pl-9" />
        </div>
        <div className="flex flex-wrap items-center gap-1.5">
          <button type="button" onClick={() => setRole('all')} className={`min-h-8 rounded-full border px-3 text-xs font-medium ${role === 'all' ? 'border-brand-600 bg-brand-600 text-white' : 'border-ink-200 text-ink-700'}`}>{t('common.all')}</button>
          {ROLES.map((r) => (
            <button key={r} type="button" onClick={() => setRole(r)} className={`min-h-8 rounded-full border px-3 text-xs font-medium ${role === r ? 'border-brand-600 bg-brand-600 text-white' : 'border-ink-200 text-ink-700'}`}>{t(`role.${r}`)}</button>
          ))}
          <span className="ml-auto text-[10px] text-ink-400">{list.length} {t('common.results').toLowerCase()}</span>
