import fs from 'node:fs'
import path from 'node:path'

const walk = (d) =>
  fs.readdirSync(d, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)],
  )
const files = walk('src').filter((f) => /\.(tsx?|ts)$/.test(f))
const keys = new Set()
for (const f of files) {
  const s = fs.readFileSync(f, 'utf8')
  for (const m of s.matchAll(/\bt\(\s*'([^']+)'/g)) keys.add(m[1])
}
const readDict = (file) => {
  const src = fs.readFileSync(file, 'utf8')
  const out = {}
  for (const m of src.matchAll(/'([^']+)':\s*(?:'((?:[^'\\]|\\.)*)')/g)) out[m[1]] = m[2]
  return out
}
const en = readDict('src/lib/i18n/en.ts')
const hi = readDict('src/lib/i18n/hi.ts')
const missingEn = [...keys].filter((k) => !(k in en)).sort()
const missingHi = [...keys].filter((k) => !(k in hi)).sort()
console.log('literal keys used:', keys.size)
console.log('missing in en:', missingEn.length)
console.log(missingEn.join('\n'))
console.log('missing in hi:', missingHi.length)
console.log(missingHi.join('\n'))

